INSERT INTO `logros` (`id_logro`, `nombre`, `descripcion`, `icono_url`) VALUES
	(1, 'Primera Sangre', 'Has completado tu primer test', 'assets/img/logros/primero.png'),
	(2, 'Racha de Fuego', 'Has aprobado 5 test seguidos', 'assets/img/logros/fuego.png'),
	(3, 'Test Perfecto', 'Has aprobado un test sin ningún fallo', 'assets/img/logros/perfecto.png');
INSERT INTO `preguntas` (`id_pregunta`, `texto`, `opcion_a`, `opcion_b`, `opcion_c`, `correcta`, `id_tema`, `imagen_url`, `fuente`) VALUES
	(1, '¿Qué indica la señal de STOP (R-2)?', 'Detenerse solo si vienen vehículos.', 'Ceder el paso, sin obligación de detenerse.', 'Detención obligatoria ante la línea de detención o, si no existe, antes de la intersección, y ceder el paso.', 'C', 1, NULL, NULL),
	(2, '¿Qué indica la señal de Ceda el Paso (R-1)?', 'Detenerse obligatoriamente.', 'Ceder el paso a los vehículos de la vía prioritaria, sin necesidad de detenerse si hay visibilidad y no se obliga a nadie a modificar su trayectoria.', 'Tenemos prioridad.', 'B', 1, NULL, NULL),
	(3, 'En una intersección sin señalización, ¿quién tiene prioridad de paso?', 'El vehículo que circula por la vía más ancha.', 'El vehículo que se aproxima por la derecha.', 'El vehículo que llega primero.', 'B', 1, NULL, NULL),
	(4, 'La señal R-3 (Calzada con prioridad) indica...', 'Prioridad en la próxima intersección únicamente.', 'Prioridad en todas las intersecciones de la calzada por la que circulamos, hasta que encontremos la señal de fin de prioridad (R-4).', 'Que debemos ceder el paso.', 'B', 1, NULL, NULL),
	(5, 'En un estrechamiento sin señalizar, ¿qué vehículo tiene prioridad?', 'El que tenga que dar marcha atrás menos distancia.', 'El vehículo que haya entrado primero.', 'El vehículo más pesado.', 'B', 1, NULL, NULL),
	(6, 'Si dos vehículos llegan a la vez a un estrechamiento en un tramo de gran pendiente, ¿quién tiene prioridad?', 'El vehículo que sube (asciende).', 'El vehículo que baja (desciende).', 'El que haya entrado primero.', 'A', 1, NULL, NULL),
	(7, 'Un vehículo en servicio de urgencia (ambulancia) circula con las señales luminosas pero sin las acústicas. ¿Tiene prioridad?', 'No, debe llevar ambas para tener prioridad.', 'Sí, siempre tiene prioridad.', 'Sí, pero debe asegurarse de no poner en riesgo a nadie y los demás usuarios deben facilitarle el paso.', 'C', 1, NULL, NULL),
	(8, 'Al salir de un garaje o un camino privado para incorporarse a la vía pública, ¿quién tiene prioridad?', 'El vehículo que sale del garaje.', 'Los peatones y vehículos que ya circulan por la vía pública.', 'Depende de la velocidad.', 'B', 1, NULL, NULL),
	(9, 'En una glorieta (rotonda), ¿quién tiene prioridad?', 'Los vehículos que van a entrar.', 'Se aplica la norma general de prioridad a la derecha.', 'Los vehículos que ya circulan por el interior de la glorieta.', 'C', 1, NULL, NULL),
	(10, 'La señal R-5 (Prioridad al sentido contrario) en un estrechamiento indica que...', 'Tenemos prioridad.', 'Debemos ceder el paso a los vehículos que vengan en sentido contrario.', 'La circulación está prohibida en ese tramo.', 'B', 1, NULL, NULL),
	(11, 'La señal R-6 (Prioridad respecto al sentido contrario) en un estrechamiento indica que...', 'Tenemos prioridad de paso sobre los vehículos que vengan en sentido contrario.', 'Debemos ceder el paso.', 'Es una calzada de sentido único.', 'A', 1, NULL, NULL),
	(12, 'Un tranvía y un turismo llegan a una intersección sin señales que regulen la prioridad. ¿Quién pasa primero?', 'El turismo, si viene por la derecha.', 'El tranvía, que tiene prioridad sobre los demás vehículos.', 'El que vaya más rápido.', 'B', 1, NULL, NULL),
	(13, '¿Qué debe hacer ante una señal de \'Paso a Nivel con Barreras\' (P-7)?', 'Pasar rápido si la barrera está subida.', 'Moderar la velocidad y detenerse si la barrera está en movimiento o bajada.', 'Detenerse siempre, aunque la barrera esté subida.', 'B', 1, NULL, NULL),
	(14, '¿Qué debe hacer al incorporarse a una autopista desde un carril de aceleración?', 'Detenerse al final del carril y esperar.', 'Ceder el paso a los vehículos que circulan por la autopista, adaptando la velocidad para incorporarse.', 'Entrar directamente, ya que tiene prioridad.', 'B', 1, NULL, NULL),
	(15, 'Los animales en una cañada debidamente señalizada (señal P-23), ¿tienen prioridad?', 'Sí, tienen prioridad de paso.', 'No, deben esperar a los vehículos.', 'Solo si van acompañados de un pastor.', 'A', 1, NULL, NULL),
	(16, '¿Cuál es la velocidad máxima genérica para un turismo en autopista o autovía?', '100 km/h', '120 km/h', '90 km/h', 'B', 2, NULL, NULL),
	(17, '¿Cuál es la velocidad máxima genérica para un turismo en una carretera convencional con un carril por sentido (arcén de menos de 1,5m)?', '90 km/h', '100 km/h', '80 km/h', 'A', 2, NULL, NULL),
	(18, 'En vías urbanas de un solo carril por sentido de circulación, ¿cuál es la velocidad máxima genérica?', '50 km/h', '20 km/h', '30 km/h', 'C', 2, NULL, NULL),
	(19, 'En vías urbanas con plataforma única (calzada y acera al mismo nivel), ¿cuál es la velocidad máxima?', '30 km/h', '20 km/h', '50 km/h', 'B', 2, NULL, NULL),
	(20, '¿Qué es la distancia de reacción?', 'La distancia que recorre el vehículo desde que el conductor pisa el freno hasta que se detiene.', 'La distancia que recorre el vehículo desde que el conductor ve un obstáculo hasta que pisa el freno.', 'La suma de la distancia de reacción y frenado.', 'B', 2, NULL, NULL),
	(21, '¿Qué es la distancia de frenado?', 'La distancia recorrida desde que se percibe el peligro.', 'La distancia recorrida desde que se pisa el freno hasta la detención total.', 'Es siempre la misma, independientemente de la velocidad.', 'B', 2, NULL, NULL),
	(22, 'La distancia de detención es...', 'La suma de la distancia de reacción más la distancia de frenado.', 'La misma que la distancia de reacción.', 'La misma que la distancia de frenado.', 'A', 2, NULL, NULL),
	(23, 'Si la calzada está mojada, la distancia de frenado...', 'Disminuye.', 'No se ve afectada.', 'Aumenta considerablemente, pudiendo ser el doble que en seco.', 'C', 2, NULL, NULL),
	(24, '¿De qué depende el tiempo de reacción?', 'Del estado de los frenos y neumáticos.', 'Del estado del conductor (fatiga, sueño, alcohol, medicamentos).', 'De la velocidad del vehículo.', 'B', 2, NULL, NULL),
	(25, '¿Qué distancia de seguridad frontal debe mantener en un túnel si no tiene intención de adelantar?', '50 metros o 2 segundos.', '100 metros o un intervalo de 4 segundos.', 'La que el conductor considere oportuna.', 'B', 2, NULL, NULL),
	(26, '¿Cuál es la velocidad mínima permitida para un turismo en autopista?', '60 km/h', '50 km/h', 'No hay velocidad mínima.', 'A', 2, NULL, NULL),
	(27, 'Un vehículo que circula a velocidad anormalmente reducida...', 'Circula 10 km/h por debajo de la máxima.', 'Circula por debajo de la velocidad mínima permitida para esa vía sin causa justificada.', 'Debe encender las luces de emergencia.', 'B', 2, NULL, NULL),
	(28, '¿Está permitido superar la velocidad máxima para adelantar en carreteras convencionales?', 'Sí, los turismos y motocicletas en 20 km/h.', 'No, desde 2021 está prohibido superar los límites de velocidad para adelantar.', 'Sí, pero solo si el vehículo adelantado va muy lento.', 'B', 2, NULL, NULL),
	(29, 'La distancia de seguridad lateral al adelantar a un ciclista fuera de poblado debe ser de...', '1 metro.', 'Mínimo 1,5 metros.', 'La anchura de un carril.', 'B', 2, NULL, NULL),
	(30, 'Si duplica la velocidad, ¿qué ocurre con la distancia de frenado?', 'Se duplica (se multiplica por 2).', 'Se cuadruplica (se multiplica por 4).', 'No varía.', 'B', 2, NULL, NULL),
	(31, 'Antes de iniciar una maniobra, ¿cuál es la regla de seguridad que debe aplicar?', 'Señalizar, Maniobrar, Observar.', 'Observar (Retrovisor), Señalizar, Maniobrar (RSM).', 'Maniobrar, Observar, Señalizar.', 'B', 3, NULL, NULL),
	(32, '¿Cómo debe señalizar una maniobra de desplazamiento lateral?', 'Con los indicadores de dirección (intermitentes).', 'Con las luces de emergencia.', 'Con el brazo, obligatoriamente.', 'A', 3, NULL, NULL),
	(33, '¿Está permitido adelantar por la derecha?', 'No, nunca. El adelantamiento se hace por la izquierda.', 'Sí, si el vehículo de delante indica su intención de girar a la izquierda o detenerse en ese lado.', 'Sí, en autopistas siempre.', 'B', 3, NULL, NULL),
	(34, '¿Dónde está prohibido adelantar, como norma general?', 'En todas las rectas.', 'En curvas y cambios de rasante de visibilidad reducida.', 'En autovías.', 'B', 3, NULL, NULL),
	(35, 'Para realizar un giro a la izquierda en una vía de doble sentido, ¿dónde debe situarse?', 'Pegado al borde derecho de la calzada.', 'En el centro, junto al eje longitudinal de la calzada, sin invadir el sentido contrario.', 'En el arcén.', 'B', 3, NULL, NULL),
	(36, 'Para girar a la derecha, ¿dónde debe situarse?', 'En el carril izquierdo.', 'En el centro de la calzada.', 'Lo más cerca posible del borde derecho de la calzada.', 'C', 3, NULL, NULL),
	(37, '¿Está permitido dar marcha atrás en una autopista o autovía?', 'Sí, si nos hemos pasado la salida, como máximo 15 metros.', 'No, está totalmente prohibido invadir la calzada para dar marcha atrás.', 'Sí, pero solo por el arcén.', 'B', 3, NULL, NULL),
	(38, '¿Cuándo se considera \'parada\'?', 'Inmovilización voluntaria por un tiempo inferior a dos minutos, sin que el conductor abandone el vehículo.', 'Inmovilización por necesidades del tráfico (ej. un semáforo).', 'Inmovilización por un tiempo superior a dos minutos.', 'A', 3, NULL, NULL),
	(39, '¿Cuándo se considera \'estacionamiento\'?', 'Inmovilización por menos de dos minutos.', 'Cualquier inmovilización voluntaria que no sea una parada ni una detención.', 'Detenerse en un STOP.', 'B', 3, NULL, NULL),
	(40, '¿Dónde está prohibido parar y estacionar?', 'En un carril bus.', 'En una calle residencial.', 'A 20 metros de una esquina.', 'A', 3, NULL, NULL),
	(41, '¿Está permitido estacionar en doble fila?', 'Sí, si es menos de 2 minutos.', 'No, está prohibido. (Solo se permite parar si no hay alternativa y no se obstaculiza).', 'Sí, si dejamos las luces de emergencia.', 'B', 3, NULL, NULL),
	(42, 'Al adelantar a un ciclista en vía interurbana, ¿es obligatorio invadir el carril contiguo?', 'Sí, siempre, aunque haya línea continua.', 'Es obligatorio invadir parcial o totalmente el carril contiguo, incluso pisando línea continua, para garantizar la separación lateral de 1,5 metros.', 'No, está prohibido invadir el carril contiguo.', 'B', 3, NULL, NULL),
	(43, '¿Está permitido hacer un cambio de sentido (dar media vuelta) en un túnel?', 'Sí, si hay buena visibilidad.', 'No, está prohibido.', 'Solo si es un túnel corto.', 'B', 3, NULL, NULL),
	(44, '¿Cuándo debe quitar el indicador de dirección (intermitente)?', 'Cuando el vehículo haya adoptado la nueva trayectoria, es decir, al finalizar la maniobra.', 'Justo antes de empezar a girar el volante.', 'Da igual, se quita solo.', 'A', 3, NULL, NULL),
	(45, 'En una calzada de tres carriles y doble sentido, ¿para qué se utiliza el carril central?', 'Para circular en el sentido que se desee.', 'Para realizar adelantamientos y giros a la izquierda (en ambos sentidos).', 'Solo para vehículos lentos.', 'B', 3, NULL, NULL),
	(46, 'Como norma general, en una vía de 3 carriles para el mismo sentido (ej. autopista), ¿por qué carril debe circular?', 'Por el carril derecho, utilizando los demás para adelantar.', 'Por el carril central, para dejar el derecho a los lentos.', 'Por el que más convenga a su destino.', 'A', 4, NULL, NULL),
	(47, '¿Cuándo está permitido utilizar las señales acústicas (claxon) en poblado?', 'Para saludar a un conocido.', 'Para avisar al coche de delante de que el semáforo está verde.', 'Exclusivamente para evitar un accidente.', 'C', 4, NULL, NULL),
	(48, 'Fuera de poblado, ¿se puede usar el claxon para advertir la intención de adelantar?', 'Sí, está permitido.', 'No, está prohibido.', 'Solo si el otro conductor no se aparta.', 'A', 4, NULL, NULL),
	(49, 'La carga de un turismo, ¿puede sobresalir por los laterales?', 'Sí, hasta 40 cm por cada lado.', 'No, en los vehículos destinados al transporte de personas, la carga no puede sobresalir lateralmente.', 'Sí, si va bien sujeta.', 'B', 4, NULL, NULL),
	(50, '¿Cuánto puede sobresalir una carga indivisible por la parte posterior de un turismo?', 'Un 10% de la longitud del vehículo.', 'Un 15% de la longitud del vehículo.', 'No puede sobresalir.', 'B', 4, NULL, NULL),
	(51, '¿Cómo se debe señalizar la carga que sobresale por detrás?', 'Con una luz roja de noche, y de día con el panel V-20 (rayas rojas y blancas).', 'Con un trapo rojo.', 'Con las luces de emergencia.', 'A', 4, NULL, NULL),
	(52, '¿Puede un turismo con un solo ocupante (el conductor) circular por un carril VAO?', 'Sí, si paga un peaje especial.', 'No, salvo que tenga la etiqueta CERO emisiones de la DGT o el distintivo V-15 de movilidad reducida.', 'Sí, en cualquier caso.', 'B', 4, NULL, NULL),
	(53, '¿Cuál es la tasa máxima de alcoholemia en aire espirado para un conductor general?', '0,50 mg/l', '0,25 mg/l', '0,15 mg/l', 'B', 4, NULL, NULL),
	(54, '¿Cuál es la tasa máxima de alcoholemia en aire espirado para un conductor novel (menos de 2 años de carnet)?', '0,25 mg/l', '0,15 mg/l', '0,0 mg/l', 'B', 4, NULL, NULL),
	(55, 'Negarse a someterse a las pruebas de detección de alcohol o drogas es...', 'Una infracción administrativa leve.', 'Un derecho del conductor.', 'Un delito tipificado en el Código Penal.', 'C', 4, NULL, NULL),
	(56, 'Utilizar el teléfono móvil sujetándolo con la mano mientras se conduce...', 'Es una infracción leve si no se está hablando.', 'Es una infracción grave que conlleva la pérdida de 6 puntos.', 'Está permitido si el coche está detenido en un semáforo.', 'B', 4, NULL, NULL),
	(57, 'Un turismo con un remolque ligero (MMA <= 750 kg), ¿qué documentación necesita?', 'Permiso de circulación propio y seguro aparte.', 'No necesita documentación especial, solo la ficha técnica del remolque. El seguro del coche lo cubre.', 'Matrícula roja.', 'B', 4, NULL, NULL),
	(58, 'Un turismo con un remolque no ligero (MMA > 750 kg) necesita...', 'Permiso de circulación propio (matrícula roja), seguro propio e ITV.', 'Solo la matrícula del coche.', 'No necesita seguro propio.', 'A', 4, NULL, NULL),
	(59, '¿Por dónde deben circular los Vehículos de Movilidad Personal (VMP) o patinetes eléctricos?', 'Por la acera, a baja velocidad.', 'Por la calzada, preferentemente por carriles bici si existen.', 'Por vías interurbanas.', 'B', 4, NULL, NULL),
	(60, '¿Tienen permitido los VMP (patinetes) circular por travesías o túneles urbanos?', 'Sí, en todos los casos.', 'No, tienen prohibida la circulación en travesías, vías interurbanas, autopistas, autovías y túneles urbanos.', 'Solo por túneles urbanos.', 'B', 4, NULL, NULL),
	(61, '¿Es obligatorio el uso del cinturón de seguridad en los asientos traseros?', 'No, solo es recomendable.', 'Sí, en todas las vías (urbanas e interurbanas) y para todos los ocupantes.', 'Solo en vías interurbanas.', 'B', 5, NULL, NULL),
	(62, '¿Quién está exento de usar el cinturón de seguridad EN POBLADO?', 'Todos los pasajeros de los asientos traseros.', 'Los conductores de taxi cuando están de servicio.', 'Cualquier conductor en un trayecto corto.', 'B', 5, NULL, NULL),
	(63, 'Si el vehículo dispone de airbag, ¿sustituye este al cinturón de seguridad?', 'Sí, el airbag es más moderno y sustituye al cinturón.', 'No, el airbag es un complemento. Su máxima eficacia se logra en combinación con el cinturón.', 'Solo sustituye al cinturón en ciudad.', 'B', 5, NULL, NULL),
	(64, '¿Hasta qué altura deben los menores de edad utilizar un Sistema de Retención Infantil (SRI)?', 'Hasta los 12 años, independientemente de la altura.', 'Hasta que midan 1,50 m.', 'Hasta que alcancen los 1,35 metros de altura.', 'C', 5, NULL, NULL),
	(65, 'Como norma general, ¿dónde deben viajar los menores de 1,35 m?', 'En los asientos traseros, con su SRI homologado.', 'En el asiento del copiloto, para ir más vigilados.', 'En cualquier asiento, con el cinturón de adulto.', 'A', 5, NULL, NULL),
	(66, 'Si instala una silla infantil (SRI) en el asiento del copiloto, en sentido contrario a la marcha, ¿qué precaución es obligatoria?', 'Avisar al resto de pasajeros.', 'Desactivar el airbag frontal del pasajero.', 'Poner el asiento lo más adelante posible.', 'B', 5, NULL, NULL),
	(67, '¿Cuál es la finalidad principal del reposacabezas?', 'Aumentar la comodidad del conductor.', 'Proteger del sol.', 'Evitar el \'latigazo cervical\' en caso de colisión por alcance.', 'C', 5, NULL, NULL),
	(68, '¿Cómo debe estar ajustado el reposacabezas?', 'Lo más bajo posible, a la altura del cuello.', 'La parte superior del reposacabezas debe quedar a la altura de la parte superior de la cabeza (o los ojos).', 'Separado de la cabeza al menos 10 cm.', 'B', 5, NULL, NULL),
	(69, '¿Es obligatorio el casco para los menores de 16 años que montan en bicicleta?', 'Sí, siempre, tanto en vía urbana como interurbana.', 'Solo en vías interurbanas.', 'No, es solo recomendable.', 'A', 5, NULL, NULL),
	(70, 'Para un ciclista mayor de 16 años, ¿cuándo es obligatorio el casco?', 'Siempre.', 'Solo en vías interurbanas.', 'Nunca.', 'B', 5, NULL, NULL),
	(71, '¿Es obligatorio llevar en el turismo un chaleco reflectante?', 'No, es opcional.', 'Sí, al menos uno, y debe guardarse en un lugar accesible (ej. la guantera), no en el maletero.', 'Sí, uno por cada plaza del vehículo.', 'B', 5, NULL, NULL),
	(72, '¿Cuándo debe usar el chaleco reflectante?', 'Siempre que conduzca de noche.', 'Al salir del vehículo e invadir la calzada o el arcén de vías interurbanas.', 'Solo si la avería es en el motor.', 'B', 5, NULL, NULL),
	(73, 'El dispositivo de preseñalización de peligro V-16 (luz de emergencia naranja), ¿sustituye a los triángulos?', 'Sí, se puede usar uno u otro (y a partir de 2026 solo será válida la V-16 conectada).', 'No, hay que llevar siempre los dos triángulos.', 'Solo sustituye a los triángulos de noche.', 'A', 5, NULL, NULL),
	(74, '¿Es obligatorio el uso de casco para los conductores de VMP (patinetes eléctricos)?', 'Sí, el Reglamento General de Circulación lo establece como obligatorio.', 'No, es solo recomendable.', 'Solo si lo indica una ordenanza municipal.', 'A', 5, NULL, NULL),
	(75, 'La \'zona de incertidumbre\' de un peatón o ciclista es...', 'La zona por donde van a cruzar seguro.', 'El espacio que les rodea, dentro del cual pueden moverse de forma imprevista.', 'Solo la tienen los niños.', 'B', 5, NULL, NULL),
	(76, '¿Qué es el \'efecto submarino\' del cinturón de seguridad?', 'Cuando el cinturón se moja y no funciona.', 'Cuando el cuerpo se desliza por debajo de la banda abdominal del cinturón en un accidente.', 'Cuando el cinturón aprieta demasiado.', 'B', 5, NULL, NULL),
	(77, '¿Qué es el ABS (Sistema Antibloqueo de Frenos)?', 'Un sistema que acorta siempre la distancia de frenado.', 'Un sistema que evita que las ruedas se bloqueen durante una frenada brusca, permitiendo mantener el control de la dirección.', 'Un sistema que frena el coche automáticamente.', 'B', 6, NULL, NULL),
	(78, 'Si su vehículo tiene ABS y necesita hacer una frenada de emergencia, ¿cómo debe actuar?', 'Pisar el freno y el embrague a fondo y de forma continua, sin soltar el freno.', 'Pisar el freno de forma intermitente (bombear).', 'Usar solo el freno de mano.', 'A', 6, NULL, NULL),
	(79, '¿Qué es el ESP (Control de Estabilidad)?', 'Un sistema que avisa si nos salimos del carril.', 'Un sistema que ayuda al conductor a mantener la trayectoria del vehículo en caso de derrape, frenando selectivamente las ruedas.', 'El sistema de navegación GPS.', 'B', 6, NULL, NULL),
	(80, '¿Cuándo se debe comprobar la presión de los neumáticos?', 'Con los neumáticos calientes, después de un viaje largo.', 'Con los neumáticos fríos (o habiendo rodado menos de 3 km).', 'Da igual, la presión no varía.', 'B', 6, NULL, NULL),
	(81, 'Circular con una presión de neumáticos inferior a la recomendada...', 'Aumenta el consumo de combustible y el desgaste por los bordes del neumático.', 'Mejora el agarre.', 'Desgasta más el centro del neumático.', 'A', 6, NULL, NULL),
	(82, 'Circular con una presión de neumáticos superior a la recomendada...', 'Aumenta el agarre.', 'Desgasta el neumático de forma irregular por el centro y reduce la superficie de contacto (agarre).', 'Reduce el consumo de combustible sin ningún riesgo.', 'B', 6, NULL, NULL),
	(83, '¿Cuál es la profundidad mínima legal del dibujo de un neumático?', '1,6 mm', '2,0 mm', '0,8 mm', 'A', 6, NULL, NULL),
	(84, '¿Qué indica el testigo de la batería (rojo) si se enciende mientras conduce?', 'Que la batería está llena.', 'Que hay un problema en el sistema de carga (alternador) o la batería no está cargando.', 'Que debe cambiar la batería inmediatamente.', 'B', 6, NULL, NULL),
	(85, '¿Qué indica el testigo de presión de aceite (aceitera roja) si se enciende en marcha?', 'Que falta poco para el cambio de aceite.', 'Que la presión del aceite es insuficiente, debiendo detener el motor inmediatamente.', 'Que el nivel de aceite es demasiado alto.', 'B', 6, NULL, NULL),
	(86, '¿Qué es el \'aquaplaning\'?', 'Conducir por la playa.', 'La pérdida de contacto del neumático con el asfalto debido a una capa de agua.', 'Un tipo de neumático especial para lluvia.', 'B', 6, NULL, NULL),
	(87, '¿Es obligatorio llevar una rueda de repuesto?', 'Sí, siempre.', 'No, se puede sustituir por una rueda de uso temporal o un kit de reparación de pinchazos.', 'Solo en viajes largos.', 'B', 6, NULL, NULL),
	(88, 'El filtro de aire del motor, ¿para qué sirve?', 'Para limpiar el aire que entra en el habitáculo.', 'Para limpiar el aire que entra en el motor para la combustión.', 'Para filtrar el aceite.', 'B', 6, NULL, NULL),
	(89, 'Un nivel bajo de líquido refrigerante puede provocar...', 'Que el coche gaste más gasolina.', 'Un sobrecalentamiento del motor.', 'Que los frenos fallen.', 'B', 6, NULL, NULL),
	(90, '¿Se debe cambiar el líquido de frenos?', 'No, dura toda la vida del coche.', 'Sí, según las indicaciones del fabricante, ya que absorbe humedad y pierde eficacia.', 'Solo si se gastan las pastillas.', 'B', 6, NULL, NULL),
	(91, 'Si nota que al frenar tiene que pisar el pedal mucho más a fondo de lo normal (pedal esponjoso), ¿a qué puede deberse?', 'A un nivel bajo de líquido de frenos o aire en el circuito.', 'A que las pastillas son nuevas.', 'A un fallo en el ABS.', 'A', 6, NULL, NULL),
	(92, '¿Qué permiso de conducción autoriza a conducir un turismo (MMA <= 3.500 kg) con un remolque de 750 kg de MMA?', 'El permiso B.', 'El permiso B+E.', 'El permiso A2.', 'A', 7, NULL, NULL),
	(93, 'Con el permiso B, ¿se puede conducir una motocicleta de 125 cc?', 'No, nunca.', 'Sí, pero solo si se tiene una antigüedad del permiso B de más de 3 años y solo en territorio nacional.', 'Sí, desde el primer día.', 'B', 7, NULL, NULL),
	(94, '¿Es obligatorio llevar el permiso de conducción (físico o digital en miDGT) mientras conduce?', 'No, solo el DNI.', 'Sí, es obligatorio.', 'No, los agentes lo pueden comprobar telemáticamente.', 'B', 7, NULL, NULL),
	(95, '¿Qué otros documentos del vehículo son obligatorios llevar?', 'El permiso de circulación y la tarjeta de ITV (con la pegatina visible).', 'El manual del vehículo.', 'La factura de compra.', 'A', 7, NULL, NULL),
	(96, '¿Es obligatorio llevar el recibo del pago del seguro?', 'Sí, es obligatorio llevar el último recibo.', 'No, no es obligatorio llevarlo, aunque el vehículo sí debe tener seguro. Los agentes pueden comprobarlo telemáticamente.', 'Solo si el coche es nuevo.', 'B', 7, NULL, NULL),
	(97, '¿Cuándo debe pasar un turismo nuevo su primera ITV?', 'A los 2 años de la primera matriculación.', 'A los 4 años de la primera matriculación.', 'Al año.', 'B', 7, NULL, NULL),
	(98, 'Un turismo de más de 10 años de antigüedad, ¿cada cuánto debe pasar la ITV?', 'Cada 6 meses (semestralmente).', 'Cada año (anualmente).', 'Cada 2 años (bienalmente).', 'B', 7, NULL, NULL),
	(99, 'Un turismo de entre 4 y 10 años, ¿cada cuánto pasa la ITV?', 'Cada año.', 'Cada 2 años (bienalmente).', 'Cada 6 meses.', 'B', 7, NULL, NULL),
	(100, 'Si se ve implicado en un accidente con heridos, ¿cuál es el orden de actuación (conducta PAS)?', 'Socorrer, Avisar, Proteger.', 'Proteger (la zona), Avisar (a emergencias 112), Socorrer (a los heridos).', 'Avisar, Socorrer, Proteger.', 'B', 7, NULL, NULL),
	(101, 'Al socorrer a un herido de accidente de tráfico, ¿debe darle de beber (ej. agua)?', 'Sí, si lo pide.', 'No, como norma general no se debe dar comida ni bebida a un herido.', 'Solo si la bebida es isotónica.', 'B', 7, NULL, NULL),
	(102, 'Si encuentra un motorista accidentado, ¿debe quitarle el casco?', 'Sí, siempre, para ver si respira.', 'No, como norma general no se debe quitar el casco, salvo que no respire y sea necesario para hacer la reanimación (RCP).', 'Sí, si está consciente.', 'B', 7, NULL, NULL),
	(103, '¿Qué es la \'hora dorada\' en un accidente?', 'El tiempo que tarda en llegar la grúa.', 'La primera hora tras el accidente, crucial para la supervivencia de los heridos graves.', 'La hora en la que se producen más accidentes (atardecer).', 'B', 7, NULL, NULL),
	(104, 'Si su permiso de conducción caduca, ¿cuánto tiempo tiene para renovarlo?', 'Se puede renovar desde 3 meses antes de caducar, y no hay límite de tiempo después (pero no se puede conducir con él caducado).', 'Debe renovarlo el día exacto.', 'Si caduca, hay que volver a examinarse.', 'A', 7, NULL, NULL),
	(105, '¿Cuántos puntos tiene un conductor novel al obtener su primer permiso?', '12 puntos.', '8 puntos.', '15 puntos.', 'B', 7, NULL, NULL),
	(106, 'Tras dos años sin cometer infracciones que resten puntos, un conductor novel (que empezó con 8) pasará a tener...', '10 puntos.', '12 puntos.', '15 puntos.', 'B', 7, NULL, NULL),
	(107, '¿Qué es el \'parte amistoso\' o Declaración Amistosa de Accidente (DAA)?', 'Un documento para avisar a la policía.', 'Un documento que rellena el taller.', 'Un formulario para agilizar los trámites con las aseguradoras en accidentes leves (sin heridos) y donde hay acuerdo.', 'C', 7, NULL, NULL),
	(108, '¿Qué luces debe llevar encendidas un vehículo circulando de noche por una vía urbana suficientemente iluminada?', 'Posición y cruce (cortas).', 'Posición y carretera (largas).', 'Solo posición.', 'A', 8, NULL, NULL),
	(109, '¿Qué luces debe llevar encendidas de noche en una vía interurbana (carretera) insuficientemente iluminada?', 'Posición y cruce (cortas).', 'Posición y carretera (largas), si no deslumbra a nadie.', 'Solo las de carretera.', 'B', 8, NULL, NULL),
	(110, 'Circula con las luces de carretera (largas) y se cruza con otro vehículo. ¿Qué debe hacer?', 'Cambiar a las de cruce (cortas) para no deslumbrarle.', 'Mantener las largas para ver mejor.', 'Dar ráfagas con las largas.', 'A', 8, NULL, NULL),
	(111, 'Si circula detrás de otro vehículo y lo va a adelantar, ¿cuándo debe quitar las luces largas?', 'Justo al ponerme a su altura.', 'Cuando el adelantamiento haya terminado.', 'Antes de iniciar el adelantamiento, para no deslumbrar al conductor por sus retrovisores.', 'C', 8, NULL, NULL),
	(112, '¿Cuándo es obligatorio usar el alumbrado de corto alcance (cruce) durante el día?', 'Al circular por carriles reversibles o carriles de sentido contrario al habitual.', 'Siempre.', 'Nunca, de día no es obligatorio.', 'A', 8, NULL, NULL),
	(113, 'Si hay niebla densa, ¿qué luces debe encender?', 'Luces de posición + cruce + antiniebla delantera (si la tiene). La antiniebla trasera también es obligatoria con niebla densa.', 'Solo las de posición.', 'Las luces de carretera (largas), porque alumbran más.', 'A', 8, NULL, NULL),
	(114, '¿Está permitido usar la luz antiniebla trasera si llueve ligeramente?', 'Sí, mejora la visibilidad.', 'No, solo debe usarse en condiciones muy adversas (niebla densa, lluvia muy intensa), ya que es muy molesta.', 'Sí, siempre que llueva.', 'B', 8, NULL, NULL),
	(115, '¿Cuándo se deben usar las luces de emergencia (warning)?', 'Para estacionar en doble fila.', 'Para indicar una inmovilización por avería, una frenada de emergencia para evitar un atasco, o cuando el vehículo representa un peligro.', 'Para avisar de que vas a aparcar.', 'B', 8, NULL, NULL),
	(116, '¿Qué indican los indicadores de dirección (intermitentes)?', 'La intención de realizar una maniobra (giro, desplazamiento lateral).', 'Prioridad de paso.', 'Que el vehículo está averiado.', 'A', 8, NULL, NULL),
	(117, '¿Está permitido realizar \'ráfagas\' (destellos con la luz larga/corta) para advertir de un peligro?', 'Sí, para advertir de un accidente o un obstáculo, o para evitar un accidente.', 'No, está prohibido.', 'Sí, para avisar de la presencia de un control policial.', 'A', 8, NULL, NULL),
	(118, 'Si su vehículo queda inmovilizado en la calzada por avería de noche, ¿qué luces debe dejar encendidas?', 'Ninguna, para no gastar batería.', 'Las luces de posición (y/o las de emergencia si es necesario).', 'Las luces de cruce.', 'B', 8, NULL, NULL),
	(119, 'En un túnel suficientemente iluminado, ¿es obligatorio encender alguna luz?', 'No, si está bien iluminado.', 'Sí, al menos posición y cruce.', 'Solo las de posición.', 'B', 8, NULL, NULL),
	(120, '¿Qué indica la luz de marcha atrás?', 'Que el vehículo va a frenar.', 'Indica a los demás usuarios que el vehículo está realizando (o va a realizar) la maniobra de marcha atrás.', 'Que el vehículo está aparcando.', 'B', 8, NULL, NULL),
	(121, 'Las luces de la matrícula trasera...', 'Son opcionales.', 'Deben encenderse siempre que lo hagan las de posición.', 'Solo se encienden al frenar.', 'B', 8, NULL, NULL),
	(122, '¿Las motocicletas deben llevar la luz de cruce encendida durante el día?', 'Sí, es obligatorio en cualquier tipo de vía.', 'No, solo de noche.', 'Solo en carretera.', 'A', 8, NULL, NULL),
	(123, '¿Quiénes son considerados \'usuarios vulnerables\' en el tráfico?', 'Los conductores de camiones.', 'Peatones, ciclistas y conductores de motocicletas.', 'Los conductores de autobús.', 'B', 9, NULL, NULL),
	(124, 'Al aproximarse a un paso de peatones señalizado, ¿qué debe hacer?', 'Acelerar para pasar antes que los peatones.', 'Moderar la velocidad y detenerse si hay peatones cruzando o con intención de cruzar.', 'Tocar el claxon para avisar.', 'B', 9, NULL, NULL),
	(125, 'Un peatón que empuja un carrito de bebé, ¿por dónde debe circular si no hay acera?', 'Por la derecha de la calzada.', 'Por el arcén de la derecha.', 'Por el arcén de la izquierda (para ver de frente a los vehículos que se acercan), o si no es posible, por la derecha.', 'C', 9, NULL, NULL),
	(126, 'Un grupo de peatones (en comitiva o procesión), ¿por dónde debe circular?', 'Por el arcén derecho.', 'Por el arcén izquierdo.', 'Por el centro de la calzada.', 'A', 9, NULL, NULL),
	(127, 'Las bicicletas, ¿tienen permitido circular por autopista?', 'Sí, por el arcén.', 'No, tienen prohibida la circulación por autopistas y autovías (salvo excepciones muy concretas para mayores de 14 años en autovía).', 'Sí, si van en grupo.', 'B', 9, NULL, NULL),
	(128, 'En un paso para ciclistas debidamente señalizado, ¿quién tiene prioridad?', 'El vehículo a motor.', 'El ciclista.', 'El que llegue primero.', 'B', 9, NULL, NULL),
	(129, 'Al adelantar a un ciclista o grupo de ciclistas, ¿qué separación lateral debe dejar?', '50 centímetros.', 'Un mínimo de 1,5 metros, pudiendo invadir el carril contrario (incluso con línea continua) si la seguridad lo permite.', 'No es necesario dejar separación, solo rebasarlos.', 'B', 9, NULL, NULL),
	(130, '¿Pueden los ciclistas circular en columna de a dos (en paralelo)?', 'Sí, excepto en tramos sin visibilidad o cuando formen aglomeraciones.', 'No, deben circular siempre en fila (uno detrás de otro).', 'Solo en ciudad.', 'A', 9, NULL, NULL),
	(131, 'Las motocicletas, ¿pueden usar el arcén para circular?', 'Sí, si van a baja velocidad.', 'No, deben circular por la calzada, como norma general.', 'Sí, para adelantar por la derecha.', 'B', 9, NULL, NULL),
	(132, 'Al tomar una curva, ¿qué debe tener en cuenta respecto a las motocicletas?', 'Que pueden frenar más rápido que un coche.', 'Que necesitan inclinarse para tomar la curva, ocupando más espacio del carril.', 'Que siempre van por el centro del carril.', 'B', 9, NULL, NULL),
	(133, 'Las personas mayores como peatones...', 'Suelen ser más rápidas y ágiles.', 'Pueden tener problemas de oído o vista, y reaccionar más lento.', 'Siempre cruzan por los pasos de peatones.', 'B', 9, NULL, NULL),
	(134, 'Un vehículo de movilidad reducida (silla de ruedas eléctrica), ¿es considerado peatón?', 'No, es un vehículo a motor.', 'Sí, a efectos de circulación, si lo hace a paso de persona, se asimila a un peatón y debe ir por las aceras o zonas peatonales.', 'Debe circular por el carril bici.', 'B', 9, NULL, NULL),
	(135, '¿Es obligatorio para los ciclistas llevar timbre?', 'Sí, es obligatorio.', 'No, es opcional.', 'Solo de noche.', 'A', 9, NULL, NULL),
	(136, 'De noche, un ciclista en vía interurbana, ¿qué debe llevar?', 'Luz de posición delantera (blanca), trasera (roja) y catadióptrico trasero. Es recomendable prenda reflectante.', 'Solo ropa reflectante.', 'No puede circular de noche.', 'A', 9, NULL, NULL),
	(137, 'Al acercarse a un autobús en una parada, especialmente si es de transporte escolar...', 'Debe acelerar para pasarlo cuanto antes.', 'Debe moderar la velocidad y estar atento, ya que pueden cruzar peatones (niños) por delante o detrás del autobús.', 'Debe detenerse obligatoriamente detrás del autobús.', 'B', 9, NULL, NULL),
	(138, '¿Cuáles son los principales factores de riesgo en la conducción?', 'El vehículo (fallos mecánicos).', 'La vía (mal estado, clima).', 'El factor humano (distracciones, alcohol, fatiga, velocidad).', 'C', 10, NULL, NULL),
	(139, 'El alcohol, incluso en pequeñas dosis...', 'Mejora los reflejos.', 'Aumenta el tiempo de reacción y disminuye la capacidad de percepción.', 'No afecta a la conducción si se está acostumbrado.', 'B', 10, NULL, NULL),
	(140, 'El alcohol produce en el conductor...', 'Una falsa sensación de seguridad y euforia.', 'Una mayor prudencia.', 'Una mejor visión periférica.', 'A', 10, NULL, NULL),
	(141, 'La fatiga al volante...', 'Hace que los movimientos sean más rápidos y precisos.', 'Aumenta el tiempo de reacción y favorece las distracciones.', 'Solo aparece en viajes largos.', 'B', 10, NULL, NULL),
	(142, '¿Qué síntomas indican la aparición de la fatiga?', 'Visión clara y concentración.', 'Necesidad de moverse en el asiento, parpadeo constante, pesadez en los ojos.', 'Ganas de correr más.', 'B', 10, NULL, NULL),
	(143, 'Para combatir la fatiga, ¿qué es lo más recomendable?', 'Tomar un café o bebida energética y seguir conduciendo.', 'Abrir la ventanilla o poner la música alta.', 'Detenerse a descansar en un lugar adecuado, dormir un rato y dar un paseo.', 'C', 10, NULL, NULL),
	(144, '¿Cada cuánto tiempo se recomienda descansar en un viaje largo?', 'Cada 4 horas.', 'Cada 2 horas o cada 200 km, aproximadamente.', 'Cuando se llegue al destino.', 'B', 10, NULL, NULL),
	(145, 'Los \'micro-sueños\' son...', 'Sueños cortos durante el descanso.', 'Periodos de pocos segundos en los que el conductor se queda dormido sin darse cuenta.', 'El sueño ligero antes de dormir profundamente.', 'B', 10, NULL, NULL),
	(146, 'Las distracciones al volante, como usar el móvil o el GPS...', 'Son la principal causa de accidentes en España.', 'No son peligrosas si duran pocos segundos.', 'Solo son peligrosas en autopista.', 'A', 10, NULL, NULL),
	(147, 'Programar el navegador GPS...', 'Debe hacerse antes de iniciar la marcha.', 'Se puede hacer mientras se conduce, si es rápido.', 'Solo se puede hacer en un semáforo en rojo.', 'A', 10, NULL, NULL),
	(148, 'Fumar mientras se conduce...', 'No afecta a la conducción.', 'Es una distracción, puede provocar problemas de visibilidad por el humo y ocupa una mano.', 'Ayuda a relajarse y combatir la fatiga.', 'B', 10, NULL, NULL),
	(149, 'Algunos medicamentos (antihistamínicos, ansiolíticos)...', 'Mejoran la conducción.', 'Pueden producir somnolencia y efectos similares al alcohol.', 'Solo afectan si se mezclan con alcohol.', 'B', 10, NULL, NULL),
	(150, 'El calor excesivo dentro del vehículo...', 'Favorece la aparición de la fatiga y la somnolencia.', 'Mantiene al conductor más alerta.', 'No influye en la conducción.', 'A', 10, NULL, NULL),
	(151, '¿Cómo afecta el cannabis (marihuana) a la conducción?', 'Aumenta la concentración.', 'Altera la percepción del espacio y el tiempo, y disminuye los reflejos.', 'No tiene efectos.', 'B', 10, NULL, NULL),
	(152, 'La agresividad al volante...', 'Es un rasgo de buen conductor.', 'Aumenta el riesgo de accidente al tomar decisiones impulsivas y peligrosas.', 'Solo afecta al propio conductor.', 'B', 10, NULL, NULL),
	(153, 'Un agente de tráfico con el brazo levantado verticalmente, ¿qué ordena?', 'Continuar la marcha.', 'Detenerse a todos los usuarios de la vía que se acerquen al agente (alto total).', 'Disminuir la velocidad.', 'B', 11, NULL, NULL),
	(154, 'Un agente con el brazo o brazos extendidos horizontalmente, ¿qué ordena?', 'Detenerse a todos los usuarios que corten la dirección indicada por el brazo o brazos.', 'Detenerse a todos, vengan de donde vengan.', 'Que los vehículos de los lados pueden pasar.', 'A', 11, NULL, NULL),
	(155, 'Un agente que balancea una luz roja o amarilla, ¿qué indica?', 'Que los vehículos pueden pasar.', 'Detenerse a los usuarios a los que el agente dirige la luz.', 'Peligro por obras.', 'B', 11, NULL, NULL),
	(156, 'Si un agente hace señales con el silbato, ¿qué significan los toques cortos y frecuentes?', 'Reanudar la marcha.', 'Detenerse.', 'Peligro.', 'B', 11, NULL, NULL),
	(157, 'Si un agente hace señales con el silbato, ¿qué significa un toque largo?', 'Reanudar la marcha.', 'Detenerse.', 'Girar a la izquierda.', 'A', 11, NULL, NULL),
	(158, 'En una intersección, hay un semáforo en verde y un agente ordenando detenerse. ¿Qué debe obedecer?', 'El semáforo, porque es una señal luminosa.', 'Al agente, ya que sus señales prevalecen sobre el resto de señales.', 'Lo que sea más seguro.', 'B', 11, NULL, NULL),
	(159, '¿Cuál es el orden de prioridad entre señales?', '1º Semáforos, 2º Agentes, 3º Señales Verticales.', '1º Agentes, 2º Señales de Balizamiento (obras), 3º Semáforos, 4º Señales Verticales, 5º Marcas Viales.', '1º Señales Verticales, 2º Marcas Viales, 3º Agentes.', 'B', 11, NULL, NULL),
	(160, 'Un semáforo principal circular en rojo, ¿qué indica?', 'Prohibición de pasar. Debe detenerse antes del semáforo o la línea de detención.', 'Pasar con precaución.', 'Detenerse solo si vienen peatones.', 'A', 11, NULL, NULL),
	(161, 'Un semáforo principal circular en verde, ¿qué indica?', 'Permite el paso, pero debe ceder el paso a los vehículos o peatones que ya estén en la intersección.', 'Prioridad absoluta.', 'Girar solo a la derecha.', 'A', 11, NULL, NULL),
	(162, 'Un semáforo circular con una luz amarilla fija (no intermitente), ¿qué indica?', 'Que va a cambiar a verde, hay que prepararse.', 'Que debe detenerse en condiciones de seguridad, igual que si estuviera en rojo.', 'Pasar con precaución.', 'B', 11, NULL, NULL),
	(163, 'Un semáforo con una luz amarilla intermitente, ¿qué indica?', 'Detenerse obligatoriamente.', 'Extremar la precaución y ceder el paso si es necesario (aplicando normas de prioridad).', 'Que el semáforo está averiado y no hay que hacerle caso.', 'B', 11, NULL, NULL),
	(164, 'Un semáforo con una flecha verde sobre fondo negro, ¿qué permite?', 'Seguir en la dirección de la flecha, con prioridad.', 'Seguir en la dirección de la flecha, pero cediendo el paso a los vehículos y peatones que tengan prioridad en la vía a la que se incorpora.', 'Seguir en cualquier dirección.', 'B', 11, NULL, NULL),
	(165, 'Un semáforo cuadrado con un ciclista, ¿a quién afecta?', 'A todos los vehículos.', 'Exclusivamente a los ciclos y ciclomotores.', 'Solo a los VMP (patinetes).', 'B', 11, NULL, NULL),
	(166, 'Las luces rojas intermitentes en un paso a nivel, ¿qué indican?', 'Prohibición temporal de paso por la proximidad de un tren.', 'Precaución, se puede pasar.', 'Avería en el paso a nivel.', 'A', 11, NULL, NULL),
	(167, 'Un semáforo de carril (cuadrado) con un aspa roja (X), ¿qué indica?', 'Que el carril está abierto.', 'Prohibición de ocupar ese carril.', 'Que el carril va a cerrarse.', 'B', 11, NULL, NULL),
	(168, 'Un semáforo de carril (cuadrado) con una flecha verde apuntando hacia abajo, ¿qué indica?', 'Que está permitido circular por ese carril.', 'Que debe abandonar el carril.', 'Que debe girar.', 'A', 11, NULL, NULL),
	(169, 'Las señales triangulares (con el vértice hacia arriba) indican...', 'Prohibición.', 'Peligro.', 'Obligación.', 'B', 12, NULL, NULL),
	(170, 'Las señales redondas con borde rojo indican...', 'Peligro.', 'Prohibición o Restricción.', 'Información.', 'B', 12, NULL, NULL),
	(171, 'Las señales redondas con fondo azul indican...', 'Obligación.', 'Fin de prohibición.', 'Peligro.', 'A', 12, NULL, NULL),
	(172, '¿Qué indica la señal P-1 (Intersección con prioridad)?', 'Peligro por proximidad de una intersección donde tenemos prioridad sobre la vía de la derecha.', 'Peligro por proximidad de una intersección donde debemos ceder el paso (STOP o Ceda).', 'Que debemos ceder el paso a la derecha.', 'A', 12, NULL, NULL),
	(173, '¿Qué indica la señal P-2 (Intersección con prioridad de la derecha)?', 'Peligro por intersección donde rige la norma general de prioridad de la derecha.', 'Que tenemos prioridad.', 'Un STOP.', 'A', 12, NULL, NULL),
	(174, '¿Qué indica la señal P-4 (Intersección con circulación giratoria)?', 'Una glorieta (rotonda).', 'Peligro por proximidad de una intersección donde la circulación se efectúa de forma giratoria.', 'Obligación de girar.', 'B', 12, NULL, NULL),
	(175, '¿Qué indica la señal P-20 (Peligro por proximidad de paso de peatones)?', 'Un lugar donde los peatones cruzan, pero tienen que ceder el paso.', 'Peligro por la proximidad de un paso para peatones señalizado.', 'Una zona peatonal.', 'B', 12, NULL, NULL),
	(176, '¿Qué indica la señal P-50 (Peligro por otros peligros)?', 'Un peligro no especificado por otra señal, suele ir con un panel indicando el peligro.', 'Que hay muchas señales juntas.', 'Fin de todos los peligros.', 'A', 12, NULL, NULL),
	(177, '¿Qué indica la señal R-100 (Prohibido circular)?', 'Entrada prohibida solo a camiones.', 'Prohibición de circulación a toda clase de vehículos en ambos sentidos.', 'Calle de sentido único.', 'B', 12, NULL, NULL),
	(178, '¿Qué indica la señal R-101 (Entrada prohibida)?', 'Prohibición de acceso a esa vía (es de sentido contrario).', 'Prohibición de circular en ambos sentidos.', 'Prohibido parar.', 'A', 12, NULL, NULL),
	(179, '¿Qué indica la señal R-200 (Prohibido pasar sin detenerse)?', 'Un Ceda el Paso.', 'Indica un puesto de aduana, policía, peaje, donde es obligatorio detenerse.', 'Un STOP.', 'B', 12, NULL, NULL),
	(180, '¿Qué indica la señal R-301 (Velocidad máxima 80)?', 'Prohibido circular a más de 80 km/h.', 'Velocidad mínima 80 km/h.', 'Velocidad recomendada 80 km/h.', 'A', 12, NULL, NULL),
	(181, '¿Qué indica la señal R-305 (Prohibido adelantar)?', 'Prohibido adelantar solo a camiones.', 'Prohíbe el adelantamiento a todos los vehículos a motor (excepto si se adelanta a una motocicleta y no se invade el sentido contrario).', 'Fin de prohibido adelantar.', 'B', 12, NULL, NULL),
	(182, '¿Qué indica la señal R-306 (Prohibido adelantar para camiones)?', 'Prohíbe a todos los camiones (MMA > 3.500 kg) adelantar.', 'Prohíbe a los turismos adelantar a camiones.', 'Fin de prohibición.', 'A', 12, NULL, NULL),
	(183, '¿Qué indica la señal R-308 (Estacionamiento prohibido)?', 'Prohibido parar y estacionar.', 'Prohibido estacionar (pero sí permite parar).', 'Zona de estacionamiento limitado.', 'B', 12, NULL, NULL),
	(184, '¿Qué indica la señal R-307 (Parada y estacionamiento prohibido)?', 'Prohibido estacionar, pero permite parar.', 'Prohíbe tanto la parada como el estacionamiento.', 'Solo prohíbe parar.', 'B', 12, NULL, NULL),
	(185, 'Una línea blanca longitudinal continua en la calzada, ¿qué indica?', 'Que se puede atravesar si no vienen vehículos.', 'Que ningún conductor debe atravesarla ni circular sobre ella.', 'Que el carril se va a estrechar.', 'B', 13, NULL, NULL),
	(186, '¿Se puede atravesar una línea continua para adelantar a un ciclista?', 'No, nunca.', 'Sí, si se puede mantener la distancia de 1,5m y la maniobra es segura, se puede pisar o atravesar.', 'Solo si el ciclista va por el arcén.', 'B', 13, NULL, NULL),
	(187, 'Una línea blanca longitudinal discontinua, ¿qué indica?', 'Delimita los carriles y se puede atravesar, con precaución.', 'Prohibición de atravesarla.', 'Un carril reversible.', 'A', 13, NULL, NULL),
	(188, 'Si una línea discontinua tiene los trazos muy juntos, ¿qué indica?', 'Que se puede correr más.', 'La proximidad de un tramo peligroso (curva, paso de peatones) o una línea continua.', 'Una zona de aparcamiento.', 'B', 13, NULL, NULL),
	(189, 'Si a su lado tiene una línea continua adosada a una discontinua, ¿cuál debe obedecer?', 'La línea discontinua.', 'La línea más cercana a su carril.', 'Ninguna, puedo hacer caso a la que quiera.', 'B', 13, NULL, NULL),
	(190, '¿Qué indica una línea transversal continua (línea de detención) antes de un STOP o un semáforo?', 'El lugar donde debe detenerse, sin rebasarla.', 'Un paso de peatones.', 'Es solo decorativa.', 'A', 13, NULL, NULL),
	(191, '¿Qué indica una línea transversal discontinua (línea de Ceda el Paso)?', 'El lugar donde debe detenerse si es necesario ceder el paso.', 'Un STOP.', 'Un paso de ciclistas.', 'A', 13, NULL, NULL),
	(192, '¿Qué indica un paso de peatones (marcas anchas y paralelas al eje)?', 'Un lugar donde los peatones tienen prioridad de paso.', 'Un lugar donde los vehículos tienen prioridad.', 'Una zona de velocidad 30.', 'A', 13, NULL, NULL),
	(193, '¿Qué indica una flecha de selección de carril pintada en el suelo?', 'Es una recomendación.', 'Es una obligación de seguir la dirección (o una de las direcciones) que indica la flecha si se circula por ese carril.', 'Indica la salida más próxima.', 'B', 13, NULL, NULL),
	(194, '¿Qué indica una flecha de retorno pintada en un carril de adelantamiento?', 'Que se debe volver al carril derecho lo antes posible, porque se acerca una línea continua.', 'Que se puede cambiar el sentido.', 'Que el adelantamiento está prohibido.', 'A', 13, NULL, NULL),
	(195, 'Una cuadrícula de marcas amarillas (rejilla) en una intersección, ¿qué indica?', 'Que se debe ceder el paso a la derecha.', 'Que no se debe entrar en ella si se prevé que se va a quedar detenido dentro, obstaculizando.', 'Una zona de carga y descarga.', 'B', 13, NULL, NULL),
	(196, 'Una línea amarilla continua en zigzag en el borde de la calzada, ¿qué indica?', 'Prohibición de estacionar (normalmente reservado para carga/descarga o parada de autobús).', 'Peligro por curva.', 'Zona de velocidad reducida.', 'A', 13, NULL, NULL),
	(197, 'Una línea amarilla continua en el bordillo (o junto al borde de la calzada), ¿qué indica?', 'Prohibido parar y estacionar.', 'Prohibido estacionar.', 'Zona de pago (ORA).', 'A', 13, NULL, NULL),
	(198, 'Una línea amarilla discontinua en el bordillo (o junto al borde de la calzada), ¿qué indica?', 'Prohibido estacionar (pero permite parar).', 'Prohibido parar y estacionar.', 'Lugar de carga y descarga.', 'A', 13, NULL, NULL),
	(199, 'Las marcas azules en una zona de estacionamiento indican...', 'Estacionamiento gratuito.', 'Estacionamiento reservado para personas con movilidad reducida.', 'Estacionamiento con limitación horaria (ORA) o de pago.', 'C', 13, NULL, NULL),
	(200, '¿Qué es un carril reversible?', 'Un carril que se puede usar para dar marcha atrás.', 'Un carril delimitado por líneas discontinuas dobles, cuyo sentido de circulación está regulado por semáforos de carril.', 'Un carril solo para autobuses.', 'B', 13, NULL, NULL);
