INSERT INTO `temario` (`id_tema`, `nombre_tema`, `resumen_ia`, `contenido_completo`) VALUES
	(1, 'Señales de Prioridad', 'La prioridad de paso es el conjunto de normas que determinan qué vehículo o usuario de la vía tiene preferencia para pasar en un punto conflictivo, como una intersección o un tramo estrecho. El objetivo principal de estas normas es evitar accidentes y garantizar la fluidez del tráfico.', '<div class="temario-conduccion">\r\n\r\n        <article id="tema-prioridad">\r\n            <h2>Introducción a la Prioridad de Paso</h2>\r\n            <p>La prioridad de paso es el conjunto de normas que determinan qué vehículo o usuario de la vía tiene preferencia para pasar en un punto conflictivo, como una intersección o un tramo estrecho.</p>\r\n            <p>El objetivo principal de estas normas es evitar accidentes y garantizar la fluidez del tráfico.</p>\r\n            <p>Cuando nos aproximamos a una intersección, debemos tener claro quién tiene la preferencia.</p>\r\n            <p>Esta preferencia se establece mediante diferentes tipos de señales. Si no existe ninguna señalización, se aplica la norma general de prioridad.</p>\r\n\r\n            <h3>La Norma General de Prioridad (Ausencia de Señal)</h3>\r\n            <p>En las intersecciones donde no exista ninguna señal específica que regule la prioridad (ni semáforos, ni agentes, ni señales verticales o marcas viales), se aplica la norma general:</p>\r\n            <blockquote>\r\n                <p><strong>Se debe ceder el paso a todos los vehículos que se aproximen por la derecha.</strong></p>\r\n            </blockquote>\r\n            <p>Existen excepciones a esta norma general, como por ejemplo:</p>\r\n            <ul>\r\n                <li>Los vehículos que circulan por una vía pavimentada tienen prioridad sobre los que proceden de un camino de tierra.</li>\r\n                <li>Los vehículos que circulan por raíles (tranvías) tienen prioridad, independientemente del lado por el que se aproximen.</li>\r\n                <li>En las glorietas, los vehículos que ya están circulando dentro de ella tienen prioridad sobre los que intentan acceder.</li>\r\n            </ul>\r\n\r\n            <h3>Señales de Prioridad en Intersecciones</h3>\r\n            <p>Estas señales verticales son las más comunes para gestionar la preferencia en cruces.</p>\r\n            \r\n            <h4>1. Señal R-1: Ceda el Paso</h4>\r\n            <ul>\r\n                <li><strong>Forma:</strong> Triángulo equilátero invertido, con borde rojo y fondo blanco.</li>\r\n                <li><strong>Significado:</strong> Obliga al conductor a ceder el paso a los vehículos que circulan por la vía a la que se aproxima (la vía preferente).</li>\r\n                <li><strong>Actuación:</strong> El conductor debe reducir la velocidad y, si es necesario, detenerse por completo para dejar pasar a los vehículos de la vía transversal. No es obligatorio detenerse si hay visibilidad suficiente y se comprueba que no se aproxima ningún vehículo al que obliguemos a modificar su trayectoria o velocidad.</li>\r\n            </ul>\r\n\r\n            <h4>2. Señal R-2: Detención Obligatoria (STOP)</h4>\r\n            <ul>\r\n                <li><strong>Forma:</strong> Octogonal (ocho lados), con fondo rojo y letras "STOP" en blanco.</li>\r\n                <li><strong>Significado:</strong> Obliga al conductor a detener su vehículo por completo ante la próxima línea de detención. Si la línea no existe, la detención debe efectuarse justo antes de la intersección (en el borde de la calzada transversal).</li>\r\n                <li><strong>Actuación:</strong> A diferencia del "Ceda el Paso", el <strong>"STOP"</strong> exige una <strong>detención total e inmovilización del vehículo</strong>, independientemente de si vienen o no otros vehículos. Una vez detenido, el conductor debe ceder el paso a todos los vehículos que circulen por la vía preferente antes de reanudar la marcha.</li>\r\n            </ul>\r\n\r\n            <h4>3. Señal R-3: Calzada con Prioridad</h4>\r\n            <ul>\r\n                <li><strong>Forma:</strong> Rombo (cuadrado apoyado sobre un vértice), con fondo amarillo y borde blanco.</li>\r\n                <li><strong>Significado:</strong> Indica a los conductores que circulan por esa calzada que tienen prioridad de paso en todas las intersecciones que encuentren a su paso.</li>\r\n                <li><strong>Vigencia:</strong> Esta prioridad se mantiene hasta que aparezca la señal R-4 (Fin de Prioridad).</li>\r\n            </ul>\r\n\r\n            <h4>4. Señal R-4: Fin de Prioridad</h4>\r\n            <ul>\r\n                <li><strong>Forma:</strong> Idéntica a la R-3 (rombo amarillo), pero atravesada por una franja negra diagonal.</li>\r\n                <li><strong>Significado:</strong> Indica la proximidad del lugar donde la calzada por la que circulamos pierde su prioridad.</li>\r\n                <li><strong>Actuación:</strong> Tras esta señal, en la siguiente intersección, ya no tendremos la prioridad indicada por la R-3. Deberemos estar atentos a la nueva señalización (STOP, Ceda el Paso) o, en su defecto, aplicar la norma general (ceder el paso a la derecha).</li>\r\n            </ul>\r\n\r\n            <h3>Prioridad en Tramos Estrechos</h3>\r\n            <p>Cuando dos vehículos no pueden cruzarse simultáneamente en un tramo estrecho, la prioridad se regula con dos señales específicas:</p>\r\n\r\n            <h4>1. Señal R-5: Prioridad en Sentido Contrario</h4>\r\n            <ul>\r\n                <li><strong>Forma:</strong> Circular, con borde rojo y fondo blanco. Contiene dos flechas en vertical: una roja (subiendo, a la derecha) y una negra (bajando, a la izquierda).</li>\r\n                <li><strong>Significado:</strong> Prohíbe la entrada en el paso estrecho si al hacerlo se obliga a los vehículos que circulan en sentido contrario (la flecha negra) a detenerse. Dicho de otro modo: <strong>no tenemos prioridad</strong>. Debemos esperar a que el vehículo en sentido contrario haya pasado.</li>\r\n            </ul>\r\n\r\n            <h4>2. Señal R-6: Prioridad Respecto al Sentido Contrario</h4>\r\n            <ul>\r\n                <li><strong>Forma:</strong> Cuadrada, con fondo azul. Contiene dos flechas en vertical: una blanca (subiendo, a la derecha) y una roja (bajando, a la izquierda).</li>\r\n                <li><strong>Significado:</strong> Indica que los vehículos que circulan en nuestro sentido (la flecha blanca) tienen prioridad de paso en el tramo estrecho sobre los que vienen en sentido contrario (la flecha roja).</li>\r\n            </ul>\r\n\r\n            <h3>Orden de Prelación entre Señales</h3>\r\n            <p>Es fundamental saber qué señal prevalece cuando hay varias señales que parecen contradecirse. El orden de prioridad es el siguiente (de mayor a menor importancia):</p>\r\n            <ol>\r\n                <li><strong>Señales y órdenes de los Agentes de la Circulación.</strong> (Lo que dice un policía prevalece sobre todo lo demás).</li>\r\n                <li><strong>Señalización circunstancial o de balizamiento.</strong> (Conos, barreras o señales de obras).</li>\r\n                <li><strong>Semáforos.</strong></li>\r\n                <li><strong>Señales Verticales de Circulación.</strong> (Como las señales R-1 a R-6 que acabamos de ver).</li>\r\n                <li><strong>Marcas Viales (Pintura en el suelo).</strong> (Por ejemplo, un "STOP" pintado en la calzada).</li>\r\n                <li><strong>Norma General de Circulación.</strong> (Ceder el paso a la derecha).</li>\r\n            </ol>\r\n        </article>'),
	(2, 'Velocidad y Distancias', 'La velocidad es uno de los factores más determinantes en la seguridad vial. No solo es un factor que contribuye a la probabilidad de que ocurra un accidente, sino que también es el elemento principal que determina la gravedad de las lesiones resultantes. Gestionar adecuadamente la velocidad no significa simplemente "no correr", sino adaptar la velocidad del vehículo a las circunstancias de la vía, del entorno y del propio conductor .', '<article id="tema-velocidad">\r\n            <h2>Introducción: La Velocidad como Factor de Riesgo</h2>\r\n            <p>La velocidad es uno de los factores más determinantes en la seguridad vial.</p>\r\n            <p>No solo es un factor que contribuye a la probabilidad de que ocurra un accidente, sino que también es el elemento principal que determina la gravedad de las lesiones resultantes.</p>\r\n            <p>Gestionar adecuadamente la velocidad no significa simplemente "no correr", sino <strong>adaptar la velocidad del vehículo a las circunstancias</strong> de la vía, del entorno y del propio conductor.</p>\r\n            <p>Una velocidad legal puede ser peligrosa si las condiciones no son óptimas (lluvia, niebla, tráfico denso, fatiga).</p>\r\n\r\n            <h3>Conceptos Fundamentales de Velocidad</h3>\r\n            <p>Es crucial diferenciar entre varios tipos de velocidad:</p>\r\n            \r\n            <h4>Velocidad Adecuada</h4>\r\n            <p>Es el concepto más importante. Es la velocidad que permite al conductor mantener el control total de su vehículo y reaccionar ante cualquier imprevisto.</p>\r\n            <p>Siempre debe estar por debajo del límite máximo y adaptarse a factores como:</p>\r\n            <ul>\r\n                <li><strong>El conductor:</strong> Fatiga, sueño, estado de ánimo, experiencia.</li>\r\n                <li><strong>El vehículo:</strong> Estado de los frenos, neumáticos, suspensión, carga.</li>\r\n                <li><strong>La vía:</strong> Trazado (curvas, pendientes), estado del pavimento (baches, gravilla), anchura.</li>\r\n                <li><strong>El entorno:</strong> Condiciones meteorológicas (lluvia, hielo, niebla), tráfico denso, presencia de peatones o animales.</li>\r\n            </ul>\r\n\r\n            <h4>Velocidad Legal (Máxima y Mínima)</h4>\r\n            <p>Es la establecida por las señales (límites específicos) o, en su ausencia, por la norma general (límites genéricos).</p>\r\n            <ul>\r\n                <li><strong>Velocidad Máxima:</strong> Superarla supone una infracción (velocidad excesiva).</li>\r\n                <li><strong>Velocidad Mínima:</strong> Circular por debajo del mínimo establecido (si existe) también es peligroso, ya que obstaculiza la circulación. En autopistas y autovías, la velocidad mínima genérica es la mitad de la máxima genérica (60 km/h).</li>\r\n            </ul>\r\n\r\n            <h4>Velocidad Excesiva vs. Velocidad Inadecuada</h4>\r\n            <ul>\r\n                <li><strong>Velocidad Excesiva:</strong> Es circular por encima del límite máximo legal permitido.</li>\r\n                <li><strong>Velocidad Inadecuada:</strong> Es circular dentro de los límites legales, pero sin adaptarse a las circunstancias del momento (ej. circular a 120 km/h en autopista con lluvia intensa). La velocidad inadecuada es una de las principales causas de accidente.</li>\r\n            </ul>\r\n\r\n            <h3>Límites Genéricos de Velocidad (España)</h3>\r\n            <p>Si no existe una señal que indique un límite específico, se aplican los siguientes límites genéricos:</p>\r\n            <p><em>(Tabla de límites de velocidad)</em></p>\r\n            <h3>La Importancia de las Distancias</h3>\r\n            <p>La velocidad está íntimamente ligada a las distancias que necesitamos para reaccionar y detener el vehículo. Un conductor debe ser capaz de calcular mentalmente estas distancias para mantener un espacio seguro.</p>\r\n\r\n            <h4>1. Distancia de Reacción (DR)</h4>\r\n            <p>Es la distancia que recorre el vehículo desde que el conductor <strong>percibe un peligro hasta que pisa el pedal del freno</strong>.</p>\r\n            <ul>\r\n                <li><strong>Tiempo de Reacción:</strong> Es el tiempo que transcurre en ese proceso. Un tiempo de reacción normal se sitúa entre <strong>0,75 y 1 segundo</strong>.</li>\r\n                <li><strong>Factores que la aumentan:</strong> Fatiga o sueño. Consumo de alcohol o drogas. Distracciones (móvil, GPS, radio).</li>\r\n                <li><strong>Cálculo:</strong> A 100 km/h, el coche recorre unos 28 metros por segundo. <strong>En un solo segundo de reacción, ya se han recorrido 28 metros</strong> antes siquiera de empezar a frenar.</li>\r\n            </ul>\r\n\r\n            <h4>2. Distancia de Frenado (DF)</h4>\r\n            <p>Es la distancia que recorre el vehículo desde que el conductor <strong>pisa el freno hasta que el vehículo se detiene por completo</strong>.</p>\r\n            <ul>\r\n                <li><strong>Factores que la aumentan:</strong>\r\n                    <ul>\r\n                        <li><strong>Velocidad (Si duplicas la velocidad, la distancia de frenado se multiplica por cuatro).</strong></li>\r\n                        <li><strong>Estado de la Vía</strong> (Con lluvia, se duplica; con hielo, se multiplica por diez).</li>\r\n                        <li><strong>Estado del Vehículo</strong> (Neumáticos, frenos, amortiguadores).</li>\r\n                        <li><strong>Masa</strong> (Cuanto más pesado, más le costará detenerse).</li>\r\n                    </ul>\r\n                </li>\r\n            </ul>\r\n\r\n            <h4>3. Distancia de Detención (DD)</h4>\r\n            <blockquote>\r\n                <p><strong>Distancia de Detención (DD) = Distancia de Reacción (DR) + Distancia de Frenado (DF)</strong></p>\r\n            </blockquote>\r\n\r\n            <h3>La Distancia de Seguridad (Distancia Intervehicular)</h3>\r\n            <p>Es el espacio que debemos dejar con el vehículo que circula delante de nosotros.</p>\r\n            <ul>\r\n                <li><strong>Regla General (Condiciones Óptimas):</strong> La Regla de los <strong>2 Segundos</strong>. (Contar "Mil ciento uno, mil ciento dos").</li>\r\n                <li><strong>Condiciones Adversas (Lluvia, Niebla):</strong> La Regla de los <strong>3 ó 4 Segundos</strong>.</li>\r\n            </ul>\r\n            <h4>Distancia de Seguridad en Túneles:</h4>\r\n            <ul>\r\n                <li>Para vehículos de hasta 3.500 kg (turismos): <strong>100 metros o un intervalo de 4 segundos</strong>.</li>\r\n                <li>Para vehículos de más de 3.500 kg (camiones): <strong>150 metros o un intervalo de 6 segundos</strong>.</li>\r\n            </ul>\r\n        </article>'),
	(3, 'Maniobras (Adelantamientos, Giros)', 'Se considera "maniobra" a toda alteración de la posición o la marcha normal de un vehículo en la calzada. Las maniobras básicas incluyen la incorporación al tráfico, el cambio de carril, el adelantamiento, el cambio de sentido, el giro, la marcha atrás, la parada y el estacionamiento. Dada su naturaleza (modificar la trayectoria o velocidad), toda maniobra implica un riesgo potencial.', '<article id="tema-maniobras">\r\n            <h2>Introducción: ¿Qué es una Maniobra?</h2>\r\n            <p>Se considera "maniobra" a toda alteración de la posición o la marcha normal de un vehículo en la calzada.</p>\r\n            <p>Las maniobras básicas incluyen la incorporación al tráfico, el cambio de carril, el adelantamiento, el cambio de sentido, el giro, la marcha atrás, la parada y el estacionamiento.</p>\r\n            <p>Dada su naturaleza (modificar la trayectoria o velocidad), toda maniobra implica un riesgo potencial.</p>\r\n            <p>Para minimizar este riesgo, existe una regla de oro que debe aplicarse siempre y en este orden exacto antes de iniciar cualquier maniobra.</p>\r\n\r\n            <h3>La Regla de Seguridad Fundamental: R-S-M</h3>\r\n            <p>Esta regla es la base de la conducción segura y debe automatizarse. Significa: <strong>Retrovisor - Señal - Maniobra</strong>.</p>\r\n            \r\n            <h4>R - Retrovisor (Observar / Comprobar):</h4>\r\n            <p>Antes de hacer nada, el conductor debe asegurarse de que puede realizar la maniobra sin peligro. Implica mirar por los tres espejos retrovisores y <strong>comprobar los ángulos muertos</strong>. Debemos comprobar que la vía está libre, que ningún otro vehículo ha iniciado una maniobra que interfiera con la nuestra.</p>\r\n\r\n            <h4>S - Señal (Señalizar / Advertir):</h4>\r\n            <p>Una vez comprobado que la maniobra es segura, debemos <strong>comunicar nuestra intención al resto de usuarios con suficiente antelación</strong>. La principal herramienta son los indicadores de dirección (intermitentes). <strong>La señalización no da prioridad</strong>. Es solo un aviso. El indicador debe mantenerse encendido durante toda la maniobra y apagarse al finalizarla.</p>\r\n\r\n            <h4>M - Maniobra (Ejecutar):</h4>\r\n            <p>Solo después de observar y señalizar, se ejecuta la maniobra. Debe hacerse de forma rápida pero segura, sin brusquedades, y respetando la prioridad de los demás usuarios.</p>\r\n\r\n            <h3>El Adelantamiento</h3>\r\n            <p>Es la maniobra más peligrosa en carreteras convencionales, ya que implica invadir el carril de sentido contrario.</p>\r\n\r\n            <h4>Fases del Adelantamiento (Aplicando RSM):</h4>\r\n            \r\n            <h5>Fase 1: Preparación (R - Observar)</h5>\r\n            <ul>\r\n                <li><strong>Mirar hacia atrás:</strong> Comprobar por los retrovisores que ningún vehículo que nos sigue ha iniciado ya el adelantamiento.</li>\r\n                <li><strong>Mirar hacia delante:</strong>\r\n                    <ul>\r\n                        <li>Comprobar que el vehículo al que queremos adelantar no ha señalizado su intención de adelantar a un tercero o de girar a la izquierda.</li>\r\n                        <li>Comprobar que el carril izquierdo (o de sentido contrario) está libre y que hay espacio suficiente.</li>\r\n                        <li>Comprobar la señalización: ¿La línea es discontinua? ¿Hay señales verticales que lo prohíban?</li>\r\n                    </ul>\r\n                </li>\r\n            </ul>\r\n\r\n            <h5>Fase 2: Señalización (S - Señalizar)</h5>\r\n            <p>Accionar el indicador izquierdo para advertir de nuestra intención de desplazarnos.</p>\r\n\r\n            <h5>Fase 3: Ejecución (M - Maniobra)</h5>\r\n            <p><strong>Distancia lateral:</strong> Al rebasar al vehículo, debemos dejar una <strong>distancia lateral de seguridad</strong>.</p>\r\n            <p><strong>Caso Especial (Vulnerables):</strong> Si se adelanta a peatones, ciclistas, ciclomotores... fuera de poblado, es <strong>obligatorio dejar una distancia lateral mínima de 1,5 metros</strong> y se permite invadir el carril contrario (incluso si hay línea continua, sin peligro).</p>\r\n            <p><strong>Regreso a la derecha (RSM de nuevo):</strong></p>\r\n            <ol>\r\n                <li><strong>R (Retrovisor):</strong> Antes de volver, debemos mirar por el retrovisor interior y no volver hasta que veamos la parte frontal completa del vehículo que hemos adelantado.</li>\r\n                <li><strong>S (Señalizar):</strong> Accionar el indicador derecho.</li>\r\n                <li><strong>M (Maniobra):</strong> Regresar a nuestro carril de forma suave.</li>\r\n            </ol>\r\n\r\n            <h4>Prohibiciones de Adelantamiento</h4>\r\n            <p>Está prohibido adelantar:</p>\r\n            <ul>\r\n                <li>En curvas y cambios de rasante de visibilidad reducida.</li>\r\n                <li>En pasos para peatones señalizados.</li>\r\n                <li>En pasos a nivel.</li>\r\n                <li>En intersecciones (salvo excepciones).</li>\r\n                <li>En túneles si solo hay un carril por sentido.</li>\r\n            </ul>\r\n\r\n            <h3>Los Giros (Cambios de Dirección)</h3>\r\n            <p>Consiste en tomar una dirección distinta a la que se seguía.</p>\r\n            <h4>Regla RSM aplicada a los Giros:</h4>\r\n            <ol>\r\n                <li><strong>R (Observar):</strong> Retrovisores y ángulos muertos. Vigilar a peatones y ciclistas.</li>\r\n                <li><strong>S (Señalizar):</strong> Accionar el indicador con muchísima antelación.</li>\r\n                <li><strong>M (Maniobra y Colocación):</strong>\r\n                    <ul>\r\n                        <li><strong>Fase de Aproximación:</strong> Debemos colocarnos correctamente en la calzada antes de llegar a la intersección.\r\n                            <ul>\r\n                                <li><strong>Giro a la Derecha:</strong> Nos ceñiremos lo máximo posible al <strong>borde derecho</strong>.</li>\r\n                                <li><strong>Giro a la Izquierda (en Vía de Doble Sentido):</strong> Nos ceñiremos al <strong>eje central de la calzada</strong> (la línea divisoria), sin rebasarla.</li>\r\n                                <li><strong>Giro a la Izquierda (en Vía de Sentido Único):</strong> Nos ceñiremos lo máximo posible al <strong>borde izquierdo</strong>.</li>\r\n                            </ul>\r\n                        </li>\r\n                        <li><strong>Fase de Franqueo (El Cruce):</strong>\r\n                            <ul>\r\n                                <li>Reducir la velocidad.</li>\r\n                                <li><strong>Prioridad:</strong> Al girar, perdemos la prioridad. Debemos ceder el paso:\r\n                                    <ul>\r\n                                        <li>En giros a la izquierda: Ceder el paso a <strong>todos los vehículos que vengan de frente</strong>.</li>\r\n                                        <li>En ambos giros: Ceder el paso a los <strong>peatones</strong> que estén cruzando la calzada a la que nos incorporamos.</li>\r\n                                        <li>Ceder el paso a los <strong>ciclistas</strong> que crucen por un carril bici.</li>\r\n                                    </ul>\r\n                                </li>\r\n                            </ul>\r\n                        </li>\r\n                    </ul>\r\n                </li>\r\n            </ol>\r\n        </article>'),
	(4, 'Normas de Circulación', 'Las normas de circulación son el conjunto de reglas que definen cómo deben comportarse los usuarios (conductores, peatones, ciclistas) en las vías públicas. Su objetivo es garantizar la seguridad , la fluidez y el orden del tráfico. El principio fundamental que rige toda la circulación es el de "conducción dirigida" .', '<article id="tema-normas-circulacion">\r\n            <h2>Introducción: El Objeto de las Normas</h2>\r\n            <p>Las normas de circulación son el conjunto de reglas que definen cómo deben comportarse los usuarios (conductores, peatones, ciclistas) en las vías públicas.</p>\r\n            <p>Su objetivo es garantizar la <strong>seguridad</strong>, la <strong>fluidez</strong> y el <strong>orden</strong> del tráfico.</p>\r\n            <p>El principio fundamental que rige toda la circulación es el de "conducción dirigida".</p>\r\n\r\n            <h3>Principios Básicos de Circulación</h3>\r\n            <h4>Posición en la Calzada:</h4>\r\n            <ul>\r\n                <li><strong>Norma General:</strong> Se debe circular <strong>por la derecha</strong>, lo más cerca posible del borde derecho.</li>\r\n            </ul>\r\n            <h4>Principio de Precaución:</h4>\r\n            <ul>\r\n                <li>El conductor está obligado a <strong>mantener en todo momento el control</strong> de su vehículo.</li>\r\n                <li>Debe mantener su propia libertad de movimientos, el campo de visión necesario y la <strong>atención permanente</strong> a la conducción.</li>\r\n                <li>Queda prohibido el uso de teléfonos móviles (sin manos libres), pantallas, auriculares, etc.</li>\r\n            </ul>\r\n\r\n            <h3>Utilización de Carriles</h3>\r\n            <h4>Fuera de Poblado (Carreteras, Autopistas, Autovías):</h4>\r\n            <ul>\r\n                <li><strong>Norma General:</strong> Se debe circular siempre por el <strong>carril situado más a la derecha</strong>.</li>\r\n                <li><strong>Uso del Resto de Carriles:</strong> Los demás carriles (centrales o izquierdos) se utilizarán <strong>únicamente para adelantar</strong>, facilitar una incorporación o tomar una salida a la izquierda.</li>\r\n                <li>Tras finalizar un adelantamiento, es <strong>obligatorio regresar al carril derecho</strong>.</li>\r\n            </ul>\r\n            <h4>Dentro de Poblado (Ciudades):</h4>\r\n            <ul>\r\n                <li>En calzadas con dos o más carriles para el mismo sentido: El conductor puede utilizar el <strong>carril que mejor convenga a su destino</strong>.</li>\r\n            </ul>\r\n\r\n            <h3>Carriles Especiales</h3>\r\n            <h4>Carril VAO (Vehículos de Alta Ocupación):</h4>\r\n            <ul>\r\n                <li>Reservado para vehículos que transportan un número mínimo de ocupantes (generalmente 2).</li>\r\n                <li>También pueden usarlo motocicletas, autobuses, vehículos de movilidad reducida y etiqueta CERO.</li>\r\n            </ul>\r\n            <h4>Carril Bus/Taxi:</h4>\r\n            <ul>\r\n                <li>Reservado exclusivamente para el transporte público.</li>\r\n            </ul>\r\n            <h4>Carril Reversible:</h4>\r\n            <ul>\r\n                <li>Delimitado por marcas dobles discontinuas. El sentido cambia mediante semáforos de carril.</li>\r\n                <li><strong>Obligaciones:</strong> Llevar encendida la <strong>luz de corto alcance (cruce)</strong>, día y noche, y velocidad máx. 80 / mín. 60 km/h.</li>\r\n            </ul>\r\n            <h4>Carril Adicional Circunstancial:</h4>\r\n            <ul>\r\n                <li><strong>Obligaciones:</strong> Quienes circulen por este carril y el contiguo deben llevar la luz de corto alcance y circular a máx. 80 / mín. 60 km/h.</li>\r\n            </ul>\r\n            <h4>Carril Habilitado en Sentido Contrario:</h4>\r\n            <ul>\r\n                <li>Habilitado por fluidez (atascos) o por obras.</li>\r\n                <li><strong>Obligaciones:</strong> Solo turismos sin remolque y motocicletas. Deben llevar la luz de corto alcance y circular a máx. 80 / mín. 60 km/h.</li>\r\n            </ul>\r\n\r\n            <h3>Circulación en Glorietas (Rotondas)</h3>\r\n            <ul>\r\n                <li><strong>Prioridad de Acceso:</strong> Los vehículos que circulan <strong>dentro de la glorieta tienen siempre prioridad</strong> sobre los que pretenden acceder.</li>\r\n                <li><strong>Elección de Carril:</strong> Se aplica la norma de poblado: elegimos el carril que mejor convenga al destino.</li>\r\n            </ul>\r\n            <h4>La Maniobra CRÍTICA: Salir de la Glorieta:</h4>\r\n            <ul>\r\n                <li><strong>OBLIGATORIO:</strong> Para salir, se debe hacer siempre <strong>desde el carril exterior</strong> (el carril derecho).</li>\r\n                <li><strong>PROHIBIDO:</strong> Está <strong>prohibido salir de la glorieta directamente desde un carril interior</strong>.</li>\r\n                <li><strong>Actuación:</strong> Si no podemos cambiarnos al carril exterior con seguridad, debemos <strong>dar otra vuelta completa</strong> a la glorieta.</li>\r\n            </ul>\r\n\r\n            <h3>Circulación en Túneles y Pasos Inferiores</h3>\r\n            <h4>Obligaciones:</h4>\r\n            <ul>\r\n                <li><strong>Alumbrado:</strong> Es obligatorio encender las <strong>luces de corto alcance (cruce)</strong>, como mínimo, tanto de día como de noche.</li>\r\n                <li><strong>Distancia de Seguridad:</strong> Mínimo <strong>100 metros</strong> (o 4 segundos) para vehículos ligeros, y <strong>150 metros</strong> (o 6 segundos) para vehículos pesados.</li>\r\n                <li><strong>Maniobras Prohibidas:</strong> Está prohibido parar, estacionar, cambiar el sentido de la marcha y dar marcha atrás.</li>\r\n            </ul>\r\n            <h4>En caso de Emergencia o Incendio:</h4>\r\n            <ul>\r\n                <li><strong>Atasco:</strong> Encender luces de emergencia, mantener distancia, y apagar el motor si la detención es prolongada (más de 2 minutos).</li>\r\n                <li><strong>Avería o Incendio:</strong> Intentar salir. Si no, arrimar a la derecha. Conectar emergencia. Ponerse el chaleco reflectante (antes de bajar). Colocar triángulos o luz V-16. Dirigirse al puesto SOS. En caso de incendio, abandonar el vehículo dejando las llaves puestas y caminar en sentido contrario al fuego.</li>\r\n            </ul>\r\n        </article>'),
	(5, 'Seguridad Vial (Cinturón, Casco)', 'La seguridad vial en el diseño de vehículos se divide en dos grandes categorías: Seguridad Activa (o Primaria) y Seguridad Pasiva (o Secundaria). La Seguridad Activa (frenos, ABS, ESP) evita que el accidente ocurra. La Seguridad Pasiva (cinturón, airbag, chasis) reduce los daños una vez que el accidente es inevitable.', '<article id="tema-seguridad-elementos">\r\n            <h2>Introducción: Seguridad Activa vs. Seguridad Pasiva</h2>\r\n            <h4>Seguridad Activa (o Primaria):</h4>\r\n            <ul>\r\n                <li><strong>Objetivo:</strong> <strong>Evitar que el accidente ocurra</strong>.</li>\r\n                <li><strong>Elementos:</strong> Ayudan al conductor a mantener el control (ABS, ESP, frenos, neumáticos, dirección).</li>\r\n            </ul>\r\n            <h4>Seguridad Pasiva (o Secundaria):</h4>\r\n            <ul>\r\n                <li><strong>Objetivo:</strong> <strong>Reducir al mínimo los daños</strong> y lesiones una vez que el accidente es inevitable.</li>\r\n                <li><strong>Elementos:</strong> Absorben la energía del impacto (Cinturón, airbag, chasis, reposacabezas, SRI).</li>\r\n            </ul>\r\n\r\n            <h3>El Cinturón de Seguridad: El Elemento Clave</h3>\r\n            <p>Reduce a la mitad (50%) el riesgo de muerte en accidente.</p>\r\n            <p><strong>Función:</strong> Retener el cuerpo del ocupante contra el asiento en caso de colisión, impidiendo que salga despedido.</p>\r\n            \r\n            <h4>El Efecto "Tres Golpes" (Lo que evita el cinturón):</h4>\r\n            <ol>\r\n                <li><strong>1º Golpe:</strong> Vehículo contra obstáculo.</li>\r\n                <li><strong>2º Golpe:</strong> Ocupante contra interior del vehículo (<strong>Este es el golpe que evita el cinturón</strong>).</li>\r\n                <li><strong>3º Golpe:</strong> Órganos internos contra la estructura ósea.</li>\r\n            </ol>\r\n\r\n            <h4>Obligatoriedad de Uso:</h4>\r\n            <ul>\r\n                <li>Es <strong>obligatorio para todos los ocupantes</strong> (delanteros y traseros) en todas las vías (urbanas e interurbanas).</li>\r\n                <li><strong>Responsabilidad:</strong> El conductor es responsable de los menores (≤ 135 cm). Los mayores de edad son responsables de sí mismos.</li>\r\n                <li><strong>Excepciones:</strong> Conductores al dar marcha atrás o estacionar. Personas con certificado médico. En poblado (solo ciudad): taxistas en servicio, distribuidores de mercancías (carga/descarga), conductores de vehículos de urgencia.</li>\r\n            </ul>\r\n\r\n            <h4>Colocación Correcta:</h4>\r\n            <ul>\r\n                <li><strong>Banda Superior:</strong> Por el centro de la clavícula (entre hombro y cuello) y centro del pecho.</li>\r\n                <li><strong>Banda Inferior:</strong> Sobre los huesos de la pelvis (cadera), <strong>nunca sobre el abdomen</strong>.</li>\r\n                <li><strong>Ajuste:</strong> Bien ceñido, sin holguras. No usar pinzas ni abrigos gruesos.</li>\r\n            </ul>\r\n\r\n            <h3>Sistemas de Retención Infantil (SRI)</h3>\r\n            <ul>\r\n                <li><strong>Obligatoriedad:</strong> Menores de edad con estatura igual o inferior a <strong>135 cm</strong> deben usar un SRI homologado.</li>\r\n                <li><strong>Ubicación:</strong> Preferentemente, en los <strong>asientos traseros</strong>.</li>\r\n                <li><strong>Excepción (Asiento Delantero):</strong> Solo si el vehículo no tiene asientos traseros, o si todos están ocupados por otros menores, o si no es posible instalarlos todos.</li>\r\n            </ul>\r\n            <p><strong><em>¡MUY IMPORTANTE!</em></strong> Si se coloca un SRI en el asiento del copiloto (a contramarcha), es <strong>obligatorio desactivar el airbag frontal</strong>.</p>\r\n\r\n            <h3>El Airbag (Bolsa de Aire)</h3>\r\n            <p>El airbag no sustituye al cinturón, <strong>lo complementa</strong>.</p>\r\n            <p>Solo es 100% eficaz si se usa <strong>conjuntamente con el cinturón</strong>.</p>\r\n            <p><strong>Peligro sin cinturón:</strong> El cuerpo impacta contra el airbag mientras se infla a más de 200 km/h, pudiendo causar lesiones graves o la muerte.</p>\r\n\r\n            <h3>El Casco (Motocicletas y Ciclomotores)</h3>\r\n            <h4>Obligatoriedad de Uso:</h4>\r\n            <ul>\r\n                <li>Es <strong>obligatorio</strong> para el conductor y el pasajero de motocicletas, ciclomotores, vehículos de tres ruedas y quads.</li>\r\n                <li>Debe usarse en <strong>todas las vías</strong> (urbanas e interurbanas).</li>\r\n                <li>Debe estar <strong>homologado</strong> (etiqueta ECE 22-05 o 22-06).</li>\r\n            </ul>\r\n            <h4>Excepciones:</h4>\r\n            <ul>\r\n                <li>Personas con certificado médico.</li>\r\n                <li>Vehículos con estructura de autoprotección y cinturones (si se lleva el cinturón puesto).</li>\r\n            </ul>\r\n            <h4>Tipos de Casco (De más a menos seguro):</h4>\r\n            <ol>\r\n                <li><strong>Integral:</strong> El más seguro. Una sola pieza.</li>\r\n                <li><strong>Modular (Abatible):</strong> Permite levantar la mentonera. Menos seguro. Se debe circular con la mentonera cerrada.</li>\r\n                <li><strong>Jet (Abierto):</strong> El menos seguro. Deja cara y mandíbula desprotegidas.</li>\r\n            </ol>\r\n            <h4>Uso Correcto:</h4>\r\n            <ul>\r\n                <li><strong>Talla:</strong> Debe ser la talla exacta, ni apretado ni suelto.</li>\r\n                <li><strong>Cierre:</strong> Debe ir siempre <strong>perfectamente abrochado</strong>.</li>\r\n            </ul>\r\n        </article>'),
	(6, 'Mecánica y Mantenimiento', 'El correcto mantenimiento del vehículo es un pilar fundamental de la seguridad activa . Un vehículo en mal estado (frenos desgastados, neumáticos sin dibujo, amortiguadores ineficaces) no responderá de forma predecible ante una situación de emergencia, aumentando drásticamente el riesgo de colisión.', '<article id="tema-mantenimiento">\r\n            <h2>Introducción: El Mantenimiento como Seguridad Activa</h2>\r\n            <p>El correcto mantenimiento del vehículo es un pilar fundamental de la <strong>seguridad activa</strong>.</p>\r\n            <p>Como recordatorio, la seguridad activa incluye todos los sistemas que ayudan a evitar que se produzca un accidente.</p>\r\n            <p>Un vehículo en mal estado (frenos desgastados, neumáticos sin dibujo, amortiguadores ineficaces) no responderá de forma predecible ante una situación de emergencia, aumentando drásticamente el riesgo de colisión.</p>\r\n            <p>El conductor es el principal responsable de asegurarse de que su vehículo circula en condiciones técnicas óptimas.</p>\r\n\r\n            <h3>El Triángulo de Seguridad</h3>\r\n            <h4>1. Los Neumáticos</h4>\r\n            <p>Son el único punto de contacto entre el vehículo y el asfalto.</p>\r\n            <ul>\r\n                <li><strong>Presión de Inflado:</strong>\r\n                    <ul>\r\n                        <li>Vital comprobarla regularmente (una vez al mes) y siempre <strong>con el neumático en frío</strong>.</li>\r\n                        <li>La presión correcta es la indicada por el fabricante (manual, marco de la puerta).</li>\r\n                        <li><strong>Presión Baja:</strong> Desgaste por los bordes, aumento de consumo, riesgo de reventón.</li>\r\n                        <li><strong>Presión Alta:</strong> Desgaste por el centro, pierde adherencia.</li>\r\n                    </ul>\r\n                </li>\r\n                <li><strong>Profundidad del Dibujo:</strong>\r\n                    <ul>\r\n                        <li>Esencial para evacuar agua y evitar el <strong>aquaplaning</strong>.</li>\r\n                        <li>La profundidad legal mínima permitida es de <strong>1,6 mm</strong>.</li>\r\n                        <li>Se puede comprobar usando los testigos de desgaste.</li>\r\n                    </ul>\r\n                </li>\r\n            </ul>\r\n\r\n            <h4>2. Los Frenos</h4>\r\n            <ul>\r\n                <li><strong>Comprobaciones del Conductor:</strong>\r\n                    <ul>\r\n                        <li><strong>Líquido de Frenos:</strong> Comprobar el nivel en el depósito (entre MÁXIMO y MÍNIMO). Debe sustituirse cada 2-4 años.</li>\r\n                        <li><strong>Testigo Luminoso:</strong> Luz roja (!) o (P) indica nivel bajo o freno de mano.</li>\r\n                        <li><strong>Sensaciones (Avisos):</strong> Pedal blando (aire), pedal duro (servofreno), chirrido (pastillas gastadas), vibración (discos alabeados).</li>\r\n                    </ul>\r\n                </li>\r\n            </ul>\r\n\r\n            <h4>3. Los Amortiguadores (Suspensión)</h4>\r\n            <ul>\r\n                <li><strong>Función:</strong> Mantener el neumático pegado al asfalto.</li>\r\n                <li><strong>Síntomas de Amortiguadores Gastados:</strong>\r\n                    <ul>\r\n                        <li>Aumento de la Distancia de Frenado (coche "cabecea").</li>\r\n                        <li>Pérdida de Estabilidad (coche "flanea").</li>\r\n                        <li>Aquaplaning a menor velocidad.</li>\r\n                        <li>Desgaste irregular de neumáticos.</li>\r\n                    </ul>\r\n                </li>\r\n            </ul>\r\n\r\n            <h3>Mantenimiento del Motor y Niveles (Fluidos)</h3>\r\n            <p>Comprobar con el <strong>motor frío y en llano</strong>.</p>\r\n            <h4>Aceite del Motor:</h4>\r\n            <ul>\r\n                <li><strong>Función:</strong> Lubrica, refrigera y limpia el motor.</li>\r\n                <li><strong>Comprobación (con la varilla):</strong> Nivel entre MÁXIMO y MÍNIMO.</li>\r\n                <li><strong>Testigo de Aceite:</strong> Luz roja (aceitera) indica presión insuficiente. <strong>Obliga a detener el vehículo inmediatamente</strong>.</li>\r\n            </ul>\r\n            <h4>Líquido Refrigerante (Anticongelante):</h4>\r\n            <ul>\r\n                <li><strong>Función:</strong> Mantiene la temperatura óptima (unos 90°C).</li>\r\n                <li><strong>Comprobación:</strong> Nivel en el vaso de expansión (entre MÁXIMO y MÍNIMO).</li>\r\n            </ul>\r\n            <p><strong><em>¡PELIGRO!</em></strong> Nunca abrir el tapón con el motor caliente.</p>\r\n            <h4>Líquido del Limpiaparabrisas:</h4>\r\n            <ul>\r\n                <li>Esencial para la visibilidad.</li>\r\n            </ul>\r\n\r\n            <h3>Sistema Eléctrico</h3>\r\n            <h4>Batería:</h4>\r\n            <ul>\r\n                <li><strong>Función:</strong> Acumula energía para arrancar y alimentar sistemas con motor parado.</li>\r\n                <li><strong>Mantenimiento:</strong> Vigilar que los bornes estén limpios y apretados.</li>\r\n                <li><strong>Aviso:</strong> Si al coche le cuesta arrancar, es síntoma de batería gastada.</li>\r\n            </ul>\r\n            <h4>Alumbrado:</h4>\r\n            <ul>\r\n                <li>El conductor es responsable de comprobar que todas las luces funcionan.</li>\r\n                <li>Es obligatorio llevar un juego de bombillas de repuesto (salvo LED o Xenón).</li>\r\n            </ul>\r\n        </article>'),
	(7, 'Documentación y Accidentes', 'Para poder circular legalmente por las vías públicas, es necesario que tanto el conductor como el vehículo estén debidamente autorizados y documentados. El conductor debe llevar consigo (físico o en la app miDGT) la documentación.', '<article id="tema-documentacion-accidentes">\r\n            <h2>Parte 1: Documentación Obligatoria</h2>\r\n\r\n            <h3>1. Permiso de Conducción</h3>\r\n            <p>Autoriza al titular a conducir.</p>\r\n            <ul>\r\n                <li><strong>Vigencia y Puntos:</strong>\r\n                    <ul>\r\n                        <li>Debe ser renovado periódicamente (cada 10 años hasta los 65, luego cada 5).</li>\r\n                        <li>Conducir con el permiso caducado es infracción grave.</li>\r\n                        <li>Asociado a un sistema de puntos. Se parte con 8 (noveles) o 12 (general), máx. 15.</li>\r\n                    </ul>\r\n                </li>\r\n                <li><strong>Novel:</strong> Durante el primer año, debe llevar la <strong>placa "L"</strong>.</li>\r\n            </ul>\r\n\r\n            <h3>2. Permiso de Circulación</h3>\r\n            <p>Es el "documento de identidad" del vehículo.</p>\r\n            <ul>\r\n                <li>Contiene datos del vehículo (matrícula, marca) y del titular.</li>\r\n            </ul>\r\n\r\n            <h3>3. Tarjeta de Inspección Técnica de Vehículos (Tarjeta de ITV)</h3>\r\n            <p>Acredita que el vehículo cumple las condiciones técnicas.</p>\r\n            <ul>\r\n                <li>Contiene especificaciones técnicas.</li>\r\n                <li><strong>Inspecciones Periódicas (ITV):</strong>\r\n                    <ul>\r\n                        <li>Turismo nuevo: 1ª a los 4 años. De 4 a 10 años: cada 2 años. Más de 10 años: cada año.</li>\r\n                    </ul>\r\n                </li>\r\n                <li><strong>Informe Favorable:</strong> Se anota y se da la pegatina V-19.</li>\r\n            </ul>\r\n\r\n            <h3>4. El Seguro Obligatorio (Responsabilidad Civil)</h3>\r\n            <p>Todo vehículo a motor está obligado a tener un seguro de Responsabilidad Civil (RC).</p>\r\n            <ul>\r\n                <li><strong>Función:</strong> Cubre los daños materiales y personales causados a terceros (víctimas).</li>\r\n                <li><strong>¿Hay que llevar el recibo?</strong> Ya no es obligatorio llevarlo. Los agentes lo comprueban telemáticamente.</li>\r\n                <li><strong>Consecuencias de no tener seguro:</strong> Fuerte multa e inmovilización del vehículo.</li>\r\n            </ul>\r\n\r\n            <h2>Parte 2: Actuación en Caso de Accidente</h2>\r\n            <p>Existe la obligación legal de prestar auxilio (<strong>Delito de Omisión de Socorro</strong>).</p>\r\n            <p>La actuación debe seguir la <strong>Regla PAS (Proteger - Avisar - Socorrer)</strong>.</p>\r\n\r\n            <h3>1. P - Proteger (La Zona y a las Personas)</h3>\r\n            <ul>\r\n                <li><strong>Autoprotección:</strong> Estacionar en lugar seguro, luces de emergencia.</li>\r\n                <li><strong>Chaleco Reflectante:</strong> Ponerse el chaleco <strong>ANTES de salir del vehículo</strong>.</li>\r\n                <li><strong>Señalizar el Obstáculo:</strong> Triángulos (a 50m, visibles desde 100m) o Luz V-16 (en el techo).</li>\r\n                <li><strong>Asegurar la Escena:</strong> Apagar contacto, freno de mano. No fumar.</li>\r\n                <li><strong>Asegurar a las Víctimas (Ilesos):</strong> <strong>Detrás de la barrera de protección</strong> (quitamiedos).</li>\r\n            </ul>\r\n\r\n            <h3>2. A - Avisar (A los Servicios de Emergencia)</h3>\r\n            <ul>\r\n                <li>Llamar al <strong>112</strong> (emergencias universal UE).</li>\r\n                <li><strong>Información Clave:</strong> Qué, Dónde, Quién (nº de víctimas y estado aparente).</li>\r\n                <li>No colgar nunca hasta que el operador lo indique.</li>\r\n            </ul>\r\n\r\n            <h3>3. S - Socorrer (A las Víctimas)</h3>\r\n            <p>Regla de oro: <strong>"No hacer más daño"</strong>.</p>\r\n            <h4>Reglas de Oro (Lo que NUNCA se debe hacer):</h4>\r\n            <ul>\r\n                <li><strong>NUNCA MOVER A UN HERIDO</strong> (salvo peligro inminente de muerte).</li>\r\n                <li><strong>NUNCA QUITAR EL CASCO A UN MOTORISTA</strong> (salvo RCP).</li>\r\n                <li><strong>NUNCA DARLES DE BEBER, COMER O MEDICAR</strong>.</li>\r\n            </ul>\r\n            <h4>Acciones de Socorrismo (Lo que SÍ se debe hacer):</h4>\r\n            <ul>\r\n                <li>Evaluar Víctimas.</li>\r\n                <li>Inconsciente pero respira: <strong>Posición Lateral de Seguridad (PLS)</strong>.</li>\r\n                <li>Inconsciente y NO respira: Iniciar la maniobra de <strong>RCP (30 compresiones, 2 insuflaciones)</strong>.</li>\r\n                <li>Hemorragias: <strong>Presionar directamente sobre la herida</strong>.</li>\r\n                <li>Abrigarlos: Tapar a los heridos (evitar hipotermia).</li>\r\n                <li>Acompañarlos: Hablar con los heridos conscientes, tranquilizarlos.</li>\r\n            </ul>\r\n        </article>'),
	(8, 'Alumbrado y Señalización', 'El sistema de alumbrado y señalización de un vehículo tiene una doble finalidad crítica para la seguridad vial: VER (permitir al conductor ver la vía) y SER VISTOS (permitir que los demás usuarios adviertan nuestra presencia).', '<article id="tema-alumbrado">\r\n            <h2>Introducción: El Principio de "Ver y Ser Vistos"</h2>\r\n            <p>El sistema de alumbrado y señalización de un vehículo tiene una doble finalidad crítica para la seguridad vial:</p>\r\n            <ul>\r\n                <li><strong>VER:</strong> Permitir al conductor ver la vía y su entorno en condiciones de baja luminosidad.</li>\r\n                <li><strong>SER VISTOS:</strong> Permitir que los demás usuarios de la vía adviertan nuestra presencia, posición, anchura y nuestras intenciones.</li>\r\n            </ul>\r\n            <p>La normativa sobre el alumbrado es estricta, ya que un uso incorrecto puede provocar un accidente por falta de visión o por deslumbramiento.</p>\r\n\r\n            <h3>¿Cuándo es Obligatorio el Alumbrado?</h3>\r\n            <p>Es obligatorio llevar encendido el alumbrado correspondiente en las siguientes situaciones:</p>\r\n            <ul>\r\n                <li><strong>De Noche:</strong> Desde la puesta del sol hasta su salida ("entre el ocaso y el orto").</li>\r\n                <li><strong>Túneles y Pasos Inferiores:</strong> En cualquier momento del día, aunque el túnel esté iluminado.</li>\r\n                <li><strong>Condiciones Meteorológicas Adversas:</strong> Lluvia intensa, niebla, nieve, nubes de polvo o humo.</li>\r\n                <li><strong>Carriles Especiales:</strong> En carriles reversibles, adicionales o de sentido contrario al habitual.</li>\r\n            </ul>\r\n            <p>Además, las <strong>motocicletas</strong> están obligadas a circular con la luz de corto alcance (cruce) encendida <strong>durante todo el día</strong>.</p>\r\n\r\n            <h3>Tipos de Luces y su Uso Correcto</h3>\r\n            <h4>1. Luces de Posición</h4>\r\n            <ul>\r\n                <li><strong>Color:</strong> Blancas delante, rojas detrás.</li>\r\n                <li><strong>Función:</strong> Indicar la presencia y la anchura del vehículo.</li>\r\n                <li><strong>Uso:</strong> <strong>¡PROHIBIDO CIRCULAR SOLO CON ELLAS!</strong> Deben acompañar siempre a cruce, carretera o antiniebla.</li>\r\n                <li><strong>Uso en Inmovilización:</strong> Es la única luz que se debe dejar encendida al inmovilizar el vehículo en la calzada o arcén de una vía interurbana por la noche.</li>\r\n            </ul>\r\n\r\n            <h4>2. Luces de Corto Alcance (o de Cruce)</h4>\r\n            <ul>\r\n                <li><strong>Función:</strong> Iluminar la vía sin deslumbrar a los demás.</li>\r\n                <li><strong>Uso Obligatorio:</strong> En todas las situaciones anteriores (noche, túneles, mal tiempo, carriles especiales). En <strong>Poblado</strong> (Ciudad) por la noche. En <strong>Vías Interurbanas</strong> (Carreteras) por la noche, si hay riesgo de deslumbrar o la vía está suficientemente iluminada.</li>\r\n            </ul>\r\n\r\n            <h4>3. Luces de Largo Alcance (o de Carretera)</h4>\r\n            <ul>\r\n                <li><strong>Función:</strong> Iluminar la vía a larga distancia (mínimo 100 metros).</li>\r\n                <li><strong>Uso (Solo permitido):</strong> En <strong>vías interurbanas</strong>, cuando esté <strong>insuficientemente iluminada</strong>, y <strong>no haya posibilidad de deslumbrar</strong> a nadie (ni de frente, ni por retrovisores).</li>\r\n                <li><strong>Obligación:</strong> Se deben cambiar inmediatamente a corto alcance (cruce) tan pronto como exista riesgo de deslumbramiento.</li>\r\n            </ul>\r\n\r\n            <h4>4. Luces Antiniebla (Delantera y Trasera)</h4>\r\n            <ul>\r\n                <li><strong>Antiniebla Delantera:</strong>\r\n                    <ul>\r\n                        <li>Es <strong>opcional</strong>.</li>\r\n                        <li><strong>Uso:</strong> Con niebla densa, lluvia muy intensa, fuerte nevada.</li>\r\n                        <li><strong>Uso Especial:</strong> También de noche en carreteras interurbanas estrechas (menos de 6,5m) con curvas peligrosas.</li>\r\n                    </ul>\r\n                </li>\r\n                <li><strong>Antiniebla Trasera:</strong>\r\n                    <ul>\r\n                        <li>Es <strong>obligatoria</strong> (al menos una, roja muy intensa).</li>\r\n                        <li><strong>Función:</strong> Ser vistos desde muy lejos. Es <strong>extremadamente deslumbrante</strong>.</li>\r\n                        <li><strong>Uso:</strong> Solo en condiciones <strong>muy desfavorables</strong> (niebla espesa, lluvia muy intensa).</li>\r\n                    </ul>\r\n                </li>\r\n            </ul>\r\n            <p><strong><em>¡IMPORTANTE!</em></strong> Debe apagarse en cuanto la condición mejore, ya que deslumbra al vehículo que sigue.</p>\r\n\r\n            <h3>Señalización: Advertencias Ópticas y Acústicas</h3>\r\n            <h4>1. Indicadores de Dirección (Intermitentes)</h4>\r\n            <ul>\r\n                <li>Forman parte de la regla RSM.</li>\r\n                <li><strong>Uso:</strong> Obligatorios para señalizar cualquier desplazamiento lateral, giros, adelantamientos, etc.</li>\r\n                <li>El uso del intermitente <strong>NO da prioridad</strong>. Solo informa.</li>\r\n            </ul>\r\n\r\n            <h4>2. Señal de Emergencia (Warning)</h4>\r\n            <ul>\r\n                <li>Cuatro intermitentes a la vez.</li>\r\n                <li><strong>Uso:</strong> Solo para <strong>advertir de un peligro</strong>.\r\n                    <ul>\r\n                        <li>Cuando el vehículo está inmovilizado por avería.</li>\r\n                        <li>Para advertir de una retención o frenazo brusco.</li>\r\n                    </ul>\r\n                </li>\r\n            </ul>\r\n\r\n            <h4>3. Advertencias Acústicas (Claxon)</h4>\r\n            <p>Está prohibido su uso inmotivado o para "saludar".</p>\r\n            <p><strong>Uso Permitido:</strong></p>\r\n            <ul>\r\n                <li>Para <strong>evitar un accidente</strong> inminente.</li>\r\n                <li><strong>Fuera de poblado</strong>, para advertir de nuestra presencia en curvas peligrosas.</li>\r\n                <li><strong>Fuera de poblado</strong>, para advertir la intención de <strong>adelantar</strong>.</li>\r\n                <li>En servicio de urgencia.</li>\r\n            </ul>\r\n\r\n            <h4>4. Advertencias Ópticas (Ráfagas)</h4>\r\n            <ul>\r\n                <li><strong>Usos:</strong> Mismos usos que el claxon para advertir de un adelantamiento o peligro.</li>\r\n                <li><strong>Uso Ilegal:</strong> Prohibido usar ráfagas para avisar de un control policial.</li>\r\n            </ul>\r\n        </article>'),
	(9, 'Usuarios Vulnerables (Peatones, Ciclistas)', 'Se denomina "usuarios vulnerables" a aquellos que, en caso de accidente, tienen una probabilidad mucho mayor de sufrir lesiones graves o mortales. Esto se debe a que no disponen de una carrocería o chasis que los proteja. Los principales grupos son: Peatones, Ciclistas, Conductores de ciclomotores, Motoristas y PMR.', '<article id="tema-usuarios-vulnerables">\r\n            <h2>Introducción: ¿Quiénes son los Usuarios Vulnerables?</h2>\r\n            <p>Se denomina "usuarios vulnerables" a aquellos que, en caso de accidente, tienen una probabilidad mucho mayor de sufrir lesiones graves o mortales.</p>\r\n            <p>Esto se debe a que no disponen de una carrocería o chasis que los proteja de la energía del impacto.</p>\r\n            <p>El principio fundamental es el de "responsabilidad compartida", con un mayor deber de protección por parte del conductor del vehículo más pesado.</p>\r\n            <p>El conductor de un turismo siempre debe ser consciente de que su vehículo es un riesgo para los demás y extremar la precaución.</p>\r\n            <p>Los principales grupos vulnerables son: <strong>Peatones, Ciclistas, Conductores de ciclomotores, Motoristas, Personas con Movilidad Reducida (PMR)</strong>.</p>\r\n\r\n            <h3>Los Peatones: Normas y Precauciones</h3>\r\n            <h4>¿Por dónde deben circular los peatones?</h4>\r\n            <ul>\r\n                <li><strong>Dentro de Poblado (Ciudad):</strong>\r\n                    <ul>\r\n                        <li>Deben circular por las zonas peatonales (aceras).</li>\r\n                        <li>Si no hay acera, lo más pegados posible al borde, preferentemente por su <strong>izquierda</strong>.</li>\r\n                    </ul>\r\n                </li>\r\n                <li><strong>Fuera de Poblado (Carreteras):</strong>\r\n                    <ul>\r\n                        <li><strong>Norma General:</strong> Deben circular por su <strong>izquierda</strong>, por el arcén del sentido contrario (para ver de frente a los coches).</li>\r\n                        <li><strong>Excepción:</strong> Si es más seguro, podrán hacerlo por la derecha.</li>\r\n                        <li><strong>De Noche o con Baja Visibilidad:</strong> Obligado a llevar un elemento luminoso o <strong>reflectante</strong> (chaleco) visible a 150 metros.</li>\r\n                        <li><strong>Grupos:</strong> Deben marchar en hilera (uno detrás de otro).</li>\r\n                    </ul>\r\n                </li>\r\n            </ul>\r\n\r\n            <h4>Prioridad de Paso de los Peatones</h4>\r\n            <p>Los conductores debemos ceder siempre el paso a los peatones en:</p>\r\n            <ul>\r\n                <li><strong>Pasos para peatones</strong> debidamente señalizados.</li>\r\n                <li>Al <strong>girar con nuestro vehículo</strong> (a derecha o izquierda) para entrar en otra vía, si hay peatones cruzándola.</li>\r\n                <li>Al cruzar un arcén por el que estén circulando peatones.</li>\r\n            </ul>\r\n            <p><strong>Precauciones del Conductor:</strong> Moderar la velocidad. No hacer señales al peatón para que cruce. Extremar la precaución ante niños y ancianos.</p>\r\n\r\n            <h3>Los Ciclistas: Normas y Precauciones</h3>\r\n            <h4>Equipamiento Obligatorio del Ciclista</h4>\r\n            <ul>\r\n                <li><strong>Casco:</strong> Obligatorio en vías interurbanas para todas las edades. En ciudad, obligatorio para menores de 16 años (recomendable para todos).</li>\r\n                <li><strong>Luces:</strong> De noche, luz blanca delante y luz roja detrás + catadióptrico rojo detrás.</li>\r\n                <li><strong>Prenda Reflectante:</strong> En vías interurbanas, de noche, prenda reflectante visible a 150 metros.</li>\r\n            </ul>\r\n\r\n            <h4>¿Por dónde deben circular los ciclistas?</h4>\r\n            <ul>\r\n                <li><strong>Norma General:</strong> Por el <strong>arcén de su derecha</strong>.</li>\r\n                <li>Si no hay arcén: Por la parte imprescindible del carril derecho.</li>\r\n                <li><strong>Carril-Bici:</strong> Si existe, tienen la obligación de usarlo.</li>\r\n            </ul>\r\n\r\n            <h4>Circulación en Grupo (Pelotón)</h4>\r\n            <ul>\r\n                <li>Se les permite circular en <strong>columna de a dos (en paralelo)</strong>.</li>\r\n                <li><strong>Obligación:</strong> Deberán colocarse en hilera (uno detrás de otro) en tramos sin visibilidad o cuando formen atascos.</li>\r\n            </ul>\r\n\r\n            <h4>Prioridad de Paso de los Ciclistas</h4>\r\n            <p>Tienen prioridad sobre vehículos de motor:</p>\r\n            <ul>\r\n                <li>Cuando circulen por un <strong>carril-bici</strong>, paso para ciclistas o arcén.</li>\r\n                <li>Al <strong>girar el vehículo de motor</strong> (coche) para entrar en otra vía, si hay ciclistas cruzándola.</li>\r\n                <li><strong>En un pelotón (grupo):</strong> El grupo completo se considera una <strong>única unidad indivisible</strong>. Una vez que el primer ciclista ha iniciado el cruce, el grupo entero tiene prioridad.</li>\r\n            </ul>\r\n\r\n            <h4>El Adelantamiento a Ciclistas: La Maniobra Crítica</h4>\r\n            <ul>\r\n                <li><strong>Distancia Lateral Mínima:</strong> Obligatorio dejar una separación lateral mínima de <strong>1,5 metros</strong>.</li>\r\n                <li><strong>Invasión del Carril Contiguo:</strong> El conductor <strong>debe invadir parcial o totalmente el carril contiguo</strong> para garantizar ese 1,5m.</li>\r\n                <li><strong>Línea Continua:</strong> Está <strong>permitido rebasar una línea continua</strong> para adelantar a un ciclista, siempre que se haga sin peligro.</li>\r\n            </ul>\r\n        </article>\r\n\r\n        <article id="tema-fatiga-sueno">\r\n            <h2>Introducción: El Factor Humano</h2>\r\n            <p>El conductor es la pieza más importante y, a la vez, la más falible del sistema de circulación.</p>\r\n            <p>Los factores humanos son estados psicofísicos que alteran nuestras capacidades para conducir de forma segura.</p>\r\n            <p>La fatiga y el sueño son dos de los "enemigos silenciosos" más peligrosos al volante.</p>\r\n            <p>No son estados que aparezcan de golpe, sino que se desarrollan de forma progresiva.</p>\r\n\r\n            <h3>La Fatiga</h3>\r\n            <p>Es la disminución de la capacidad física y mental para realizar una tarea.</p>\r\n            <h4>Causas de la Fatiga:</h4>\r\n            <ul>\r\n                <li><strong>El Conductor:</strong> <strong>Conducir de forma continuada sin realizar descansos</strong>. Estrés, ansiedad. Postura incorrecta.</li>\r\n                <li><strong>El Vehículo:</strong> Habitáculo mal ventilado o con temperatura excesiva (calor). Vehículo en mal estado.</li>\r\n                <li><strong>La Vía y el Entorno:</strong> Conducir de noche o con mal tiempo. Monotonía (autopistas rectas, "hipnosis de la autopista"). Complejidad (tráfico denso, atascos).</li>\r\n            </ul>\r\n\r\n            <h4>Síntomas de la Fatiga y Efectos en la Conducción</h4>\r\n            <ul>\r\n                <li><strong>Síntomas Físicos:</strong> Pesadez de párpados, picor de ojos, visión borrosa. Dolores de espalda, cuello. Necesidad de moverse en el asiento. Bostezos.</li>\r\n                <li><strong>Efectos en la Conducción:</strong>\r\n                    <ul>\r\n                        <li><strong>Aumento del Tiempo de Reacción:</strong> Es el efecto más peligroso.</li>\r\n                        <li><strong>Disminución de la Atención:</strong> Se reduce la capacidad de atender a múltiples estímulos. Efecto "visión túnel" (dejar de percibir señales o espejos).</li>\r\n                        <li><strong>Maniobras Imprecisas:</strong> Volantazos, frenazos bruscos.</li>\r\n                    </ul>\r\n                </li>\r\n            </ul>\r\n\r\n            <h4>Cómo Combatir la Fatiga</h4>\r\n            <p>La fatiga solo se combate <strong>descansando</strong>.</p>\r\n            <ul>\r\n                <li><strong>La Regla de Oro:</strong> Descansar <strong>cada 2 horas o cada 150-200 kilómetros</strong>. El descanso debe ser de 20 o 30 minutos, fuera del vehículo.</li>\r\n                <li><strong>NO sirven los remedios temporales:</strong> El café, las bebidas energéticas o la cafeína no eliminan la fatiga, solo la enmascaran. Poner la música alta o bajar la ventanilla solo despeja unos segundos.</li>\r\n                <li>Mantener una buena hidratación (agua) y evitar comidas pesadas.</li>\r\n            </ul>\r\n\r\n            <h3>La Somnolencia (El Sueño)</h3>\r\n            <p>Es la necesidad fisiológica e irrefrenable de dormir. Es infinitamente más peligrosa, porque contra el sueño no se puede luchar.</p>\r\n            <h4>Causas de la Somnolencia:</h4>\r\n            <ul>\r\n                <li>Haber dormido pocas horas.</li>\r\n                <li>Conducir durante las <strong>horas de máximo sueño</strong>: De madrugada (3:00-5:00) y después de comer (14:00-16:00).</li>\r\n                <li>Tomar comidas copiosas o alcohol.</li>\r\n            </ul>\r\n\r\n            <h4>El Microsueño:</h4>\r\n            <ul>\r\n                <li><strong>¿Qué es un microsueño?</strong> Es la pérdida de conciencia durante un período de 2 a 5 segundos. El conductor se duerme sin ser consciente.</li>\r\n                <li><strong>Peligro:</strong> Un microsueño de 4 segundos a 120 km/h significa recorrer <strong>133 metros completamente a ciegas</strong>.</li>\r\n            </ul>\r\n            <h4>Otros Síntomas:</h4>\r\n            <p>Bostezos continuos. Dificultad para mantener los ojos abiertos. Errores graves (invadir carril, volantazos). No recordar lo que ha ocurrido en los últimos kilómetros.</p>\r\n\r\n            <h4>Cómo Combatir la Somnolencia</h4>\r\n            <p>La somnolencia solo se combate <strong>DURMIENDO</strong>.</p>\r\n            <p><strong><em>¡PROHIBIDO SEGUIR!</em></strong> Ante el primer síntoma, detenerse inmediatamente en un lugar seguro.</p>\r\n            <ul>\r\n                <li><strong>La Micro-siesta:</strong> La única solución es <strong>dormir 20 o 30 minutos</strong>.</li>\r\n                <li>Tomar un café ANTES de la micro-siesta puede ayudar (tarda 20 min en hacer efecto).</li>\r\n                <li>Nunca iniciar un viaje largo si no se ha dormido lo suficiente (7-8 horas).</li>\r\n            </ul>\r\n        </article>'),
	(10, 'Factores de Riesgo (Fatiga, Sueño)', 'El conductor es la pieza más importante y, a la vez, la más falible del sistema de circulación. La fatiga y el sueño son dos de los "enemigos silenciosos" más peligrosos al volante, reduciendo drásticamente la capacidad de reacción y la toma de decisiones.', '<article id="tema-prelacion-agentes-semaforos">\r\n            <h2>Introducción: El Orden de Prioridad (Prelación)</h2>\r\n            <p>En la circulación, no todas las señales tienen la misma importancia.</p>\r\n            <p>Cuando un conductor se encuentra con varias señales que parecen contradecirse (ej. semáforo en verde y señal de STOP), debe saber cuál obedecer.</p>\r\n            <p>El orden de prioridad (prelación), del más al menos importante, es:</p>\r\n            <ol>\r\n                <li><strong>Señales y órdenes de los Agentes de la Circulación.</strong></li>\r\n                <li><strong>Señales circunstanciales o de balizamiento fijo.</strong> (Conos, barreras, obras).</li>\r\n                <li><strong>Semáforos.</strong></li>\r\n                <li><strong>Señales Verticales de Circulación.</strong> (STOP, Ceda el Paso).</li>\r\n                <li><strong>Marcas Viales</strong> (Pintura en el suelo).</li>\r\n                <li>Si no existe ninguna señal, se aplica la <strong>Norma General de Circulación</strong> (ceder paso a la derecha).</li>\r\n            </ol>\r\n\r\n            <h3>1. Señales de los Agentes de la Circulación</h3>\r\n            <p>Las órdenes de un Agente son las de <strong>máxima prioridad</strong>. Prevalecen sobre todo.</p>\r\n            \r\n            <h4>A. Señales con el Brazo (A pie firme)</h4>\r\n            <h5>Brazo levantado verticalmente:</h5>\r\n            <ul>\r\n                <li><strong>Significado:</strong> ¡Alto total!</li>\r\n                <li><strong>Obligación:</strong> Obliga a detenerse a <strong>todos los usuarios</strong> que se aproximen al agente desde <strong>cualquier dirección</strong>.</li>\r\n            </ul>\r\n            <h5>Brazo o brazos extendidos horizontalmente:</h5>\r\n            <ul>\r\n                <li><strong>Significado:</strong> ¡Alto!</li>\r\n                <li><strong>Obligación:</strong> Obliga a detenerse a todos los usuarios que se aproximen desde direcciones que <strong>corten la trayectoria</strong> indicada por el brazo (es decir, los que se aproximan <strong>de frente a él y por su espalda</strong>).</li>\r\n                <li><strong>Vigencia:</strong> Permanece en vigor aunque el agente baje los brazos, hasta que realice otra señal.</li>\r\n            </ul>\r\n            <h5>Balanceo de una luz roja o amarilla:</h5>\r\n            <ul>\r\n                <li><strong>Obligación:</strong> Detenerse a los usuarios hacia los que el agente dirija la luz.</li>\r\n            </ul>\r\n            <h5>Brazo moviéndose de arriba abajo (rápido):</h5>\r\n            <ul>\r\n                <li><strong>Obligación:</strong> Reducir la velocidad.</li>\r\n            </ul>\r\n\r\n            <h4>B. Señales con Silbato (A pie firme)</h4>\r\n            <ul>\r\n                <li><strong>Toques cortos y frecuentes:</strong> ¡Alto! (Orden de detención).</li>\r\n                <li><strong>Un toque largo:</strong> Reanudar la marcha. (Permiso para pasar).</li>\r\n            </ul>\r\n\r\n            <h4>C. Señales desde un Vehículo Policial (En movimiento)</h4>\r\n            <ul>\r\n                <li><strong>Bandera Roja:</strong> Calzada temporalmente cerrada al tráfico por detrás de la patrulla.</li>\r\n                <li><strong>Bandera Verde:</strong> Calzada de nuevo abierta al tráfico.</li>\r\n                <li><strong>Bandera Amarilla:</strong> Extremar la atención por peligro.</li>\r\n                <li><strong>Luz Roja Intermitente (desde el vehículo policial):</strong>\r\n                    <ul>\r\n                        <li><strong>Obligación:</strong> El conductor del vehículo que circula <strong>delante debe detenerse en el lado derecho</strong>.</li>\r\n                    </ul>\r\n                </li>\r\n            </ul>\r\n\r\n            <h3>2. Semáforos</h3>\r\n            <p>Ocupan el <strong>tercer nivel de prioridad</strong>. Prevalecen sobre señales verticales y marcas viales.</p>\r\n\r\n            <h4>A. Semáforos Circulares (Principales)</h4>\r\n            <ul>\r\n                <li><strong>Luz Roja Fija:</strong> No pasar. Obliga a detenerse.</li>\r\n                <li><strong>Luz Verde Fija:</strong>\r\n                    <ul>\r\n                        <li><strong>Significado:</strong> Pasar.</li>\r\n                        <li><strong><em>¡IMPORTANTE!</em></strong> Si vamos a girar (derecha o izquierda), perdemos la prioridad y debemos ceder el paso a peatones o ciclistas que estén cruzando.</li>\r\n                    </ul>\r\n                </li>\r\n                <li><strong>Luz Amarilla Fija (No intermitente):</strong>\r\n                    <ul>\r\n                        <li><strong>Significado:</strong> Detenerse. Tiene exactamente el <strong>mismo significado que la luz roja fija</strong>.</li>\r\n                        <li><strong>Excepción:</strong> Solo se permite pasar si no se puede detener en condiciones de seguridad.</li>\r\n                    </ul>\r\n                </li>\r\n                <li><strong>Luz Amarilla Intermitente (Una o dos luces):</strong>\r\n                    <ul>\r\n                        <li><strong>Significado:</strong> Precaución. No da prioridad.</li>\r\n                        <li><strong>Obligación:</strong> Si está junto a una señal (STOP, Ceda), debemos <strong>obedecer la señal vertical</strong>. Si no hay señal, aplicar la norma general (ceder paso a la derecha).</li>\r\n                    </ul>\r\n                </li>\r\n            </ul>\r\n\r\n            <h4>B. Semáforos con Flechas (Sobre fondo negro)</h4>\r\n            <ul>\r\n                <li><strong>Flecha Verde:</strong> Permite pasar <strong>únicamente en la dirección de la flecha</strong>.</li>\r\n                <li><strong><em>¡IMPORTANTE!</em></strong> No es prioridad absoluta. Debemos ceder el paso a vehículos y peatones en la vía a la que nos incorporamos.</li>\r\n                <li><strong>Flecha Roja o Amarilla Fija:</strong> Detenerse, pero solo para la dirección de la flecha.</li>\r\n            </ul>\r\n\r\n            <h4>C. Semáforos Cuadrados (De Carril)</h4>\r\n            <ul>\r\n                <li><strong>Aspa Roja (X):</strong> Prohíbe circular por ese carril.</li>\r\n                <li><strong>Flecha Verde (apuntando abajo):</strong> Permite circular por ese carril.</li>\r\n                <li><strong>Flecha Amarilla/Blanca (oblicua, intermitente):</strong> Debemos abandonar ese carril y cambiarnos al que apunta la flecha (el carril se va a cerrar).</li>\r\n            </ul>\r\n        </article>'),
	(11, 'Señales de Agentes y Semáforos', 'En la circulación, no todas las señales tienen la misma importancia. Cuando un conductor se encuentra con varias señales que parecen contradecirse, debe saber cuál obedecer. La normativa establece un orden de prioridad (prelación).', '<article id="tema-prelacion-agentes-semaforos">\r\n            <h2>Introducción: El Orden de Prioridad (Prelación)</h2>\r\n            <p>En la circulación, no todas las señales tienen la misma importancia.</p>\r\n            <p>Cuando un conductor se encuentra con varias señales que parecen contradecirse (ej. semáforo en verde y señal de STOP), debe saber cuál obedecer.</p>\r\n            <p>El orden de prioridad (prelación), del más al menos importante, es:</p>\r\n            <ol>\r\n                <li><strong>Señales y órdenes de los Agentes de la Circulación.</strong></li>\r\n                <li><strong>Señales circunstanciales o de balizamiento fijo.</strong> (Conos, barreras, obras).</li>\r\n                <li><strong>Semáforos.</strong></li>\r\n                <li><strong>Señales Verticales de Circulación.</strong> (STOP, Ceda el Paso).</li>\r\n                <li><strong>Marcas Viales</strong> (Pintura en el suelo).</li>\r\n                <li>Si no existe ninguna señal, se aplica la <strong>Norma General de Circulación</strong> (ceder paso a la derecha).</li>\r\n            </ol>\r\n\r\n            <h3>1. Señales de los Agentes de la Circulación</h3>\r\n            <p>Las órdenes de un Agente son las de <strong>máxima prioridad</strong>. Prevalecen sobre todo.</p>\r\n            \r\n            <h4>A. Señales con el Brazo (A pie firme)</h4>\r\n            <h5>Brazo levantado verticalmente:</h5>\r\n            <ul>\r\n                <li><strong>Significado:</strong> ¡Alto total!</li>\r\n                <li><strong>Obligación:</strong> Obliga a detenerse a <strong>todos los usuarios</strong> que se aproximen al agente desde <strong>cualquier dirección</strong>.</li>\r\n            </ul>\r\n            <h5>Brazo o brazos extendidos horizontalmente:</h5>\r\n            <ul>\r\n                <li><strong>Significado:</strong> ¡Alto!</li>\r\n                <li><strong>Obligación:</strong> Obliga a detenerse a todos los usuarios que se aproximen desde direcciones que <strong>corten la trayectoria</strong> indicada por el brazo (es decir, los que se aproximan <strong>de frente a él y por su espalda</strong>).</li>\r\n                <li><strong>Vigencia:</strong> Permanece en vigor aunque el agente baje los brazos, hasta que realice otra señal.</li>\r\n            </ul>\r\n            <h5>Balanceo de una luz roja o amarilla:</h5>\r\n            <ul>\r\n                <li><strong>Obligación:</strong> Detenerse a los usuarios hacia los que el agente dirija la luz.</li>\r\n            </ul>\r\n            <h5>Brazo moviéndose de arriba abajo (rápido):</h5>\r\n            <ul>\r\n                <li><strong>Obligación:</strong> Reducir la velocidad.</li>\r\n            </ul>\r\n\r\n            <h4>B. Señales con Silbato (A pie firme)</h4>\r\n            <ul>\r\n                <li><strong>Toques cortos y frecuentes:</strong> ¡Alto! (Orden de detención).</li>\r\n                <li><strong>Un toque largo:</strong> Reanudar la marcha. (Permiso para pasar).</li>\r\n            </ul>\r\n\r\n            <h4>C. Señales desde un Vehículo Policial (En movimiento)</h4>\r\n            <ul>\r\n                <li><strong>Bandera Roja:</strong> Calzada temporalmente cerrada al tráfico por detrás de la patrulla.</li>\r\n                <li><strong>Bandera Verde:</strong> Calzada de nuevo abierta al tráfico.</li>\r\n                <li><strong>Bandera Amarilla:</strong> Extremar la atención por peligro.</li>\r\n                <li><strong>Luz Roja Intermitente (desde el vehículo policial):</strong>\r\n                    <ul>\r\n                        <li><strong>Obligación:</strong> El conductor del vehículo que circula <strong>delante debe detenerse en el lado derecho</strong>.</li>\r\n                    </ul>\r\n                </li>\r\n            </ul>\r\n\r\n            <h3>2. Semáforos</h3>\r\n            <p>Ocupan el <strong>tercer nivel de prioridad</strong>. Prevalecen sobre señales verticales y marcas viales.</p>\r\n\r\n            <h4>A. Semáforos Circulares (Principales)</h4>\r\n            <ul>\r\n                <li><strong>Luz Roja Fija:</strong> No pasar. Obliga a detenerse.</li>\r\n                <li><strong>Luz Verde Fija:</strong>\r\n                    <ul>\r\n                        <li><strong>Significado:</strong> Pasar.</li>\r\n                        <li><strong><em>¡IMPORTANTE!</em></strong> Si vamos a girar (derecha o izquierda), perdemos la prioridad y debemos ceder el paso a peatones o ciclistas que estén cruzando.</li>\r\n                    </ul>\r\n                </li>\r\n                <li><strong>Luz Amarilla Fija (No intermitente):</strong>\r\n                    <ul>\r\n                        <li><strong>Significado:</strong> Detenerse. Tiene exactamente el <strong>mismo significado que la luz roja fija</strong>.</li>\r\n                        <li><strong>Excepción:</strong> Solo se permite pasar si no se puede detener en condiciones de seguridad.</li>\r\n                    </ul>\r\n                </li>\r\n                <li><strong>Luz Amarilla Intermitente (Una o dos luces):</strong>\r\n                    <ul>\r\n                        <li><strong>Significado:</strong> Precaución. No da prioridad.</li>\r\n                        <li><strong>Obligación:</strong> Si está junto a una señal (STOP, Ceda), debemos <strong>obedecer la señal vertical</strong>. Si no hay señal, aplicar la norma general (ceder paso a la derecha).</li>\r\n                    </ul>\r\n                </li>\r\n            </ul>\r\n\r\n            <h4>B. Semáforos con Flechas (Sobre fondo negro)</h4>\r\n            <ul>\r\n                <li><strong>Flecha Verde:</strong> Permite pasar <strong>únicamente en la dirección de la flecha</strong>.</li>\r\n                <li><strong><em>¡IMPORTANTE!</em></strong> No es prioridad absoluta. Debemos ceder el paso a vehículos y peatones en la vía a la que nos incorporamos.</li>\r\n                <li><strong>Flecha Roja o Amarilla Fija:</strong> Detenerse, pero solo para la dirección de la flecha.</li>\r\n            </ul>\r\n\r\n            <h4>C. Semáforos Cuadrados (De Carril)</h4>\r\n            <ul>\r\n                <li><strong>Aspa Roja (X):</strong> Prohíbe circular por ese carril.</li>\r\n                <li><strong>Flecha Verde (apuntando abajo):</strong> Permite circular por ese carril.</li>\r\n                <li><strong>Flecha Amarilla/Blanca (oblicua, intermitente):</strong> Debemos abandonar ese carril y cambiarnos al que apunta la flecha (el carril se va a cerrar).</li>\r\n            </ul>\r\n        </article>'),
	(12, 'Señales Verticales (Peligro, Prohibición)', 'Las señales verticales están montadas sobre un poste. Su función es advertir de peligros, regular (prohibir u obligar) o informar. Ocupan el 4º lugar de prioridad: prevalecen sobre las marcas viales (pintura en el suelo). Ejemplo: Si hay un STOP vertical y un "CEDA" pintado, obedecemos el STOP.', '<article id="tema-senales-verticales">\r\n            <h2>Introducción: El Papel de las Señales Verticales</h2>\r\n            <p>Las señales verticales son aquellas que están montadas sobre un poste o un pórtico.</p>\r\n            <p>Su función es advertir de peligros, regular la circulación (prohibiciones u obligaciones), o informar.</p>\r\n            <p>En el orden de prioridad (prelación), ocupan el <strong>4º lugar</strong>.</p>\r\n            <p><strong>Prevalecen sobre las Marcas Viales (pintura en el suelo)</strong>.</p>\r\n            <blockquote>\r\n                <p><strong>Ejemplo clave:</strong> Si hay una señal vertical de "STOP" (R-2) y un "CEDA EL PASO" pintado en el suelo, <strong>debemos obedecer la señal vertical (el STOP)</strong>.</p>\r\n            </blockquote>\r\n\r\n            <h3>1. Señales de Peligro (Advertencia)</h3>\r\n            <ul>\r\n                <li><strong>Forma:</strong> Triangulares (vértice hacia arriba).</li>\r\n                <li><strong>Color:</strong> Borde rojo grueso y fondo blanco (o amarillo en obras).</li>\r\n                <li><strong>Significado:</strong> Código "P". <strong>ADVIERTEN</strong> de la proximidad de un peligro. No prohíben ni obligan, solo avisan.</li>\r\n            </ul>\r\n\r\n            <h4>Ejemplos Clave de Señales de Peligro:</h4>\r\n            <ul>\r\n                <li><strong>P-1 (Intersección con prioridad):</strong> Nos advierte de un cruce donde <strong>nosotros tenemos la prioridad</strong>.</li>\r\n                <li><strong>P-2 (Intersección con prioridad de la derecha):</strong> <strong><em>¡Importante!</em></strong> Nos advierte de un cruce donde <strong>NO tenemos prioridad</strong> y debemos aplicar la norma general (ceder paso a la derecha).</li>\r\n                <li><strong>P-6 (Intersección con Ceda el Paso):</strong> Advierte proximidad de un R-1.</li>\r\n                <li><strong>P-7 (Intersección con STOP):</strong> Advierte proximidad de un R-2.</li>\r\n                <li><strong>P-13a</strong> (Curva peligrosa a la derecha).</li>\r\n                <li><strong>P-14a</strong> (Sucesión de curvas peligrosas, la primera a la derecha).</li>\r\n                <li><strong>P-15a</strong> (Resalto) / <strong>P-15b</strong> (Badén).</li>\r\n                <li><strong>P-7 (Paso a nivel CON barreras).</strong></li>\r\n                <li><strong>P-8 (Paso a nivel SIN barreras)</strong> (más peligroso).</li>\r\n                <li><strong>P-20</strong> (Peligro por peatones).</li>\r\n                <li><strong>P-21</strong> (Peligro por niños).</li>\r\n                <li><strong>P-22</strong> (Peligro por ciclistas).</li>\r\n                <li><strong>P-50 (Otros peligros):</strong> Una señal genérica (con una "!") que indica un peligro no especificado.</li>\r\n            </ul>\r\n\r\n            <h3>2. Señales de Reglamentación</h3>\r\n            <ul>\r\n                <li><strong>Forma:</strong> Circulares (como norma general).</li>\r\n                <li><strong>Significado:</strong> Indican una <strong>OBLIGACIÓN O UNA PROHIBICIÓN</strong>.</li>\r\n            </ul>\r\n\r\n            <h4>A. Señales de Prohibición</h4>\r\n            <ul>\r\n                <li><strong>Color:</strong> Borde rojo grueso, fondo blanco (o azul si es de estacionamiento).</li>\r\n                <li><strong>Significado:</strong> Código "R". <strong>PROHÍBEN</strong> una acción.</li>\r\n            </ul>\r\n            <h5>Ejemplos Clave de Prohibición:</h5>\r\n            <ul>\r\n                <li><strong>R-100 (Circulación Prohibida):</strong> Prohíbe la circulación a todo tipo de vehículos en ambos sentidos.</li>\r\n                <li><strong>R-101 (Entrada Prohibida):</strong> Es la señal de "Dirección Prohibida".</li>\r\n                <li><strong>R-301 (Velocidad Máxima):</strong> Prohíbe circular a una velocidad superior a la indicada.</li>\r\n                <li><strong>R-302 (Adelantamiento Prohibido):</strong> Prohíbe adelantar a vehículos de motor (sí se podría a bicis/motos si no se invade sentido contrario).</li>\r\n                <li><strong>R-303 (Adelantamiento Prohibido para Camiones):</strong> Prohíbe a camiones (+3.500 kg) adelantar.</li>\r\n                <li><strong>R-305</strong> (Giro a la izquierda prohibido).</li>\r\n                <li><strong>R-306</strong> (Media vuelta / Cambio de sentido prohibido).</li>\r\n            </ul>\r\n\r\n            <h4>B. Señales de Restricción de Estacionamiento</h4>\r\n            <ul>\r\n                <li><strong>R-307 (Parada y Estacionamiento Prohibido):</strong> Borde rojo, fondo azul, <strong>cruz roja (aspa)</strong>. Prohíbe ambas.</li>\r\n                <li><strong>R-308 (Estacionamiento Prohibido):</strong> Borde rojo, fondo azul, <strong>una sola barra roja diagonal</strong>. Permite la parada, prohíbe el estacionamiento.</li>\r\n                <li><strong>R-308a / R-308b (Estacionamiento Prohibido Días Impares / Pares):</strong> Con "I" o "II".</li>\r\n            </ul>\r\n\r\n            <h4>C. Señales de Obligación</h4>\r\n            <ul>\r\n                <li><strong>Forma:</strong> Circulares.</li>\r\n                <li><strong>Color:</strong> Fondo azul y símbolo en blanco.</li>\r\n                <li><strong>Significado:</strong> Código "R". <strong>OBLIGAN</strong> a seguir un comportamiento.</li>\r\n            </ul>\r\n            <h5>Ejemplos Clave de Obligación:</h5>\r\n            <ul>\r\n                <li><strong>R-400a (Sentido obligatorio):</strong> Obliga a seguir la dirección de la flecha.</li>\r\n                <li><strong>R-403a (Únicas direcciones permitidas).</strong></li>\r\n                <li><strong>R-407a (Vía obligatoria para ciclistas / Carril-Bici).</strong></li>\r\n                <li><strong>R-412 (Obligación de usar cadenas para nieve).</strong></li>\r\n                <li><strong>R-418 (Obligación de encender luces de corto alcance).</strong></li>\r\n            </ul>\r\n        </article>'),
	(13, 'Marcas Viales (Líneas en el suelo)', 'Las marcas viales ("pintura en el suelo") son líneas, flechas, símbolos y letras pintadas sobre el pavimento. Ocupan el 5º y último lugar en el orden de prioridad. Prevalecen las señales verticales sobre las marcas viales.', '<article id="tema-marcas-viales">\r\n            <h2>Introducción: El Último Nivel de Prioridad</h2>\r\n            <p>Las marcas viales, "la pintura en el suelo", son líneas, flechas, símbolos y letras pintadas sobre el pavimento.</p>\r\n            <p>Su función es regular la circulación, delimitar carriles y reforzar otras señales.</p>\r\n            <p>En el orden de prioridad, ocupan el <strong>5º y último lugar</strong>.</p>\r\n            <p>Si hay una contradicción entre una señal vertical (STOP) y una marca vial (Ceda el Paso), <strong>SIEMPRE prevalece la señal vertical</strong>.</p>\r\n\r\n            <h3>1. Marcas Longitudinales (Delimitan Carriles y Sentidos)</h3>\r\n            <h4>A. Línea Continua</h4>\r\n            <ul>\r\n                <li><strong>Significado:</strong> Prohibición absoluta de ser atravesada o de circular sobre ella.</li>\r\n                <li><strong>Excepciones (Cuándo SÍ se puede atravesar):</strong>\r\n                    <ul>\r\n                        <li>Para <strong>adelantar a ciclistas</strong>, ciclomotores, peatones, animales (dejando 1,5m y sin peligro).</li>\r\n                        <li>Para <strong>esquivar un obstáculo</strong> (ej. coche averiado).</li>\r\n                    </ul>\r\n                </li>\r\n                <li><strong>Doble Línea Continua:</strong> Tiene exactamente el mismo significado que una simple.</li>\r\n            </ul>\r\n\r\n            <h4>B. Línea Discontinua (Trazos)</h4>\r\n            <ul>\r\n                <li><strong>Significado:</strong> Permite atravesarla para realizar maniobras (cambios de carril, adelantamientos).</li>\r\n                <li><strong>Casos Especiales:</strong>\r\n                    <ul>\r\n                        <li><strong>Trazos más anchos:</strong> Indica un carril especial (Bus, aceleración).</li>\r\n                        <li><strong>Trazos más cortos y juntos:</strong> Indican la <strong>proximidad de un peligro</strong> o de una línea continua.</li>\r\n                    </ul>\r\n                </li>\r\n            </ul>\r\n\r\n            <h4>C. Línea Continua Adosada a una Discontinua</h4>\r\n            <ul>\r\n                <li><strong>Significado:</strong> Los conductores deben obedecer la línea que está <strong>de su lado</strong> (la más cercana a su carril).</li>\r\n                <li>Si tu lado es la discontinua, puedes adelantar. Si es la continua, no puedes.</li>\r\n            </ul>\r\n\r\n            <h3>2. Marcas Transversales (Cruzan la Calzada)</h3>\r\n            <h4>A. Línea de Detención Continua</h4>\r\n            <ul>\r\n                <li><strong>Significado:</strong> Indica el lugar exacto donde es <strong>obligatorio detenerse</strong>.</li>\r\n                <li><strong>Asociación:</strong> Siempre asociada a un <strong>STOP</strong>, un <strong>semáforo en rojo</strong>, un paso a nivel o un Agente.</li>\r\n            </ul>\r\n\r\n            <h4>B. Línea de Detención Discontinua</h4>\r\n            <ul>\r\n                <li><strong>Significado:</strong> Indica el lugar donde debemos detenernos si fuera necesario ceder el paso.</li>\r\n                <li><strong>Asociación:</strong> Siempre asociada a una señal de <strong>Ceda el Paso (R-1)</strong>.</li>\r\n            </ul>\r\n\r\n            <h4>C. Pasos para Peatones (Paso de Cebra)</h4>\r\n            <ul>\r\n                <li><strong>Significado:</strong> Concede <strong>prioridad de paso absoluta</strong> a los peatones.</li>\r\n            </ul>\r\n\r\n            <h4>D. Paso para Ciclistas</h4>\r\n            <ul>\r\n                <li><strong>Significado:</strong> Concede <strong>prioridad de paso</strong> a los ciclistas.</li>\r\n            </ul>\r\n\r\n            <h3>3. Otras Marcas, Símbolos e Inscripciones</h3>\r\n            <h4>A. Flechas de Selección de Carril</h4>\r\n            <ul>\r\n                <li><strong>Significado:</strong> <strong>Obligan</strong> a los conductores de ese carril a seguir la dirección que indica la flecha.</li>\r\n                <li>Si te equivocas, estás obligado a seguir la flecha.</li>\r\n            </ul>\r\n\r\n            <h4>B. Flecha de Retorno</h4>\r\n            <ul>\r\n                <li><strong>Significado:</strong> Advierte que se acerca una línea continua y que <strong>debe regresar a su carril derecho</strong>.</li>\r\n            </ul>\r\n\r\n            <h4>C. Cebreado (Zona Excluida al Tráfico)</h4>\r\n            <ul>\r\n                <li><strong>Significado:</strong> <strong>Prohibido circular, parar o estacionar</strong> sobre él.</li>\r\n            </ul>\r\n\r\n            <h4>D. Cuadrícula Amarilla (Rejilla)</h4>\r\n            <ul>\r\n                <li><strong>Significado:</strong> <strong>Prohíbe entrar en la intersección</strong> (aunque tengamos prioridad) si prevemos que podemos <strong>quedar detenidos dentro</strong>, obstaculizando.</li>\r\n            </ul>\r\n\r\n            <h4>E. Líneas de Estacionamiento (Colores)</h4>\r\n            <ul>\r\n                <li><strong>Blancas:</strong> Estacionamiento normal.</li>\r\n                <li><strong>Azules:</strong> Zona de estacionamiento regulado (ORA), de pago o tiempo limitado.</li>\r\n            </ul>\r\n\r\n            <h4>F. Marcas en el Borde de la Calzada (Colores)</h4>\r\n            <ul>\r\n                <li><strong>Línea Amarilla Continua:</strong> Parada y Estacionamiento Prohibido. (Corrección: tu docx dice Estacionamiento Prohibido, pero la norma habitual es P+E).</li>\r\n                <li><strong>Línea Amarilla Discontinua:</strong> Estacionamiento Prohibido (permite la parada). (Corrección: tu docx dice P+E, pero la norma habitual es solo E).</li>\r\n                <li><strong>Línea Amarilla en Zig-Zag:</strong> Prohibido estacionar (reservado para bus, carga/descarga).</li>\r\n            </ul>\r\n        </article>');
